INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0001', 'pdf_database', 'The airport shuttle -------- every hour from the hotel''s front entrance.', 'depart', 'was departed', 'are departing', 'departs', 'D', 'Từ vựng: airport shuttle~Xe đưa đón sân bay; entrance~ lỗi vào; depart ~ khởi hành.', 'Xe đưa đón sân bay khởi hành mỗi giờ từ lối vào phía trước của khách sạn.', 'airport shuttle~Xe đưa đón sân bay; entrance~ lỗi vào; depart ~ khởi hành.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0002', 'pdf_database', 'Trains -------- at 9:00 A.M. Monday through Friday.', 'depart', 'is departed', 'departs', 'is departing', 'A', NULL, 'Xe lửa khởi hành lúc 9:00 A.M, từ thứ Hai đến thứ Sáu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0003', 'pdf_database', 'The Globe Lighting Supply handbook ------- a list of important company telephone numbers.', 'contain', 'containing', 'are contained', 'contains', 'D', 'Từ vựng: handbook~ cẩm nang, sách; contain ~ chứa.', 'Cẩm nang Cung cấp Ánh sáng Toàn cầu chứa danh sách các số điện thoại quan trọng của công ty.', 'handbook~ cẩm nang, sách; contain ~ chứa.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0004', 'pdf_database', 'The manufacturer --------the warranty on its latest camera models by twelve months.', 'extend', 'were extended', 'extending', 'has extended', 'D', 'Từ vựng: warranty ~ bảo hành; extend ~ kéo dài, mở rộng.', 'Nhà sản xuất đã gia hạn bảo hành cho các mẫu máy ảnh mới nhất của mình thêm mười hai tháng.', 'warranty ~ bảo hành; extend ~ kéo dài, mở rộng.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0005', 'pdf_database', 'Guitarist Carlos Roldan --------- his newest music at a fund-raising concert in Madrid last month.', 'performed', 'performs', 'performing', 'will perform', 'A', 'Từ vựng: Guitarist~ nghệ sĩ guitar; fund-raising concert ~buổi hòa nhạc gây quỹ; perform~ biểu diễn.', 'Guitarist Carlos Roldan đã biểu diễn âm nhạc mới nhất của mình tại một buổi hòa nhạc gây quỹ ở Madrid vào tháng trước.', 'Guitarist~ nghệ sĩ guitar; fund-raising concert ~buổi hòa nhạc gây quỹ; perform~ biểu diễn.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0006', 'pdf_database', 'Inclement weather and a reduced workforce ------- the greatest challenges to the renovation of the Kern Science Center.', 'have posed', 'is posing', 'does pose', 'has been posed', 'A', 'Từ vựng: inclement~ xấu, khắc nghiệt; workforce~lực lượng lao động; challenge~ thử thách; renovation~ cải tạo; pose ~đặt ra.', 'Thời tiết khắc nghiệt và lực lượng lao động giảm đã đặt ra những thách thức lớn nhất đối với việc cải tạo Trung tâm Khoa học Kern.', 'inclement~ xấu, khắc nghiệt; workforce~lực lượng lao động; challenge~ thử thách; renovation~ cải tạo; pose ~đặt ra.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0007', 'pdf_database', 'By the time Ms. Valspar retires as president of Movene Technologies, she ------- to increase the company''s market share significantly.', 'manages', 'will have managed', 'managed', 'has been managing', 'B', 'Từ vựng: retire~ nghỉ hưu; market share~ thị phần; significantly~ đáng kể.', 'Trước khi bà Valspar nghỉ hưu với tư cách là chủ tịch của Movene Technologies, bà sẽ quản lý để tăng thị phần của công ty một cách đáng kể.', 'retire~ nghỉ hưu; market share~ thị phần; significantly~ đáng kể.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0008', 'pdf_database', 'Before Mr. Kim joined our company as a sales analyst, he ------- in the sales sector for several years already.', 'works', 'has worked', 'will work', 'had worked', 'D', 'Từ vựng: as ~ như là; sales analyst~ nhà phân tích bán hàng; sector ~ lĩnh vực.', 'Trước khi ông Kim gia nhập công ty chúng tôi với tư cách là một nhà phân tích bán hàng, ông đã làm việc trong lĩnh vực bán hàng được vài năm rồi.', 'as ~ như là; sales analyst~ nhà phân tích bán hàng; sector ~ lĩnh vực.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0009', 'pdf_database', 'The company -------working on the project for the main office even before it chose the land to build on.', 'will begin', 'had begun', 'has begun', 'is beginning', 'B', 'Từ vựng: main office ~ văn phòng chính; even ~ thậm chí.', 'Công ty đã bắt đầu làm việc cho dự án cho văn phòng chính ngay cả trước khi họ chọn đất để xây dựng.', 'main office ~ văn phòng chính; even ~ thậm chí.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0010', 'pdf_database', 'Following the visit to your production facility in Hong Kong next week, we ------- a comprehensive factory automation program to meet your company''s needs.', 'will create', 'was created', 'having created', 'had been creating', 'A', 'Từ vựng: main office ~ văn phòng chính; even ~ thậm chí.', 'Sau chuyến thăm cơ sở sản xuất của bạn tại Hồng Kông vào tuần tới, chúng tôi sẽ tạo ra một chương trình tự động hóa nhà máy toàn diện để đáp ứng nhu cầu của công ty bạn.', 'main office ~ văn phòng chính; even ~ thậm chí.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0011', 'pdf_database', 'In addition, the branch offices in Washington and Atlanta -------new interns last week.', 'welcome', 'welcomed', 'will welcome', 'has welcomed', 'B', 'Từ vựng: In addition~ ngoài ra, thêm vào; branch office~ văn phòng chi nhánh; intern~ thực tập sinh.', 'Ngoài ra, các văn phòng chi nhánh tại Washington và Atlanta đã chào đón thực tập sinh mới vào tuần trước.', 'In addition~ ngoài ra, thêm vào; branch office~ văn phòng chi nhánh; intern~ thực tập sinh.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0012', 'pdf_database', 'After all entries have been submitted, a panel of independent judges -------the winning slogan based on originality.', 'will choose', 'was choosing', 'choose', 'has chosen', 'A', 'Từ vựng: entry~sự ghi danh, danh sách người thi đấu; a panel~ một hội đồng; judge~ giám khảo; based on~ dựa trên; originality~tính độc đáo.', 'Sau khi tất cả danh sách được nộp, một hội đồng thẩm phán độc lập sẽ chọn khẩu hiệu chiến thắng dựa trên tính nguyên bản.', 'entry~sự ghi danh, danh sách người thi đấu; a panel~ một hội đồng; judge~ giám khảo; based on~ dựa trên; originality~tính độc đáo.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0013', 'pdf_database', 'WOCO will------- employees to Ireland to help design the plant and assist in establishing the production line.', 'sent', 'send', 'sends', 'sending', 'B', 'Từ vựng: plant ~ nhà máy; assist~ hỗ trợ; establish~ thiết lập; production line~ dây chuyền sản xuất.', 'WOCO sẽ cử nhân viên đến Ireland để giúp thiết kế nhà máy và hỗ trợ thiết lập dây chuyền sản xuất.', 'plant ~ nhà máy; assist~ hỗ trợ; establish~ thiết lập; production line~ dây chuyền sản xuất.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0014', 'pdf_database', 'Mr. Graves ------- employed by the same company in various capacities since 1988.', 'is', 'has', 'has been', 'could be', 'C', 'Từ vựng: employ~ tuyển dụng; capacity~ vị trí, khả năng; various ~ khác nhau, nhiều.', 'Ông Graves đã được thuê bởi cùng một công ty trong các vị trí khác nhau kể từ năm 1988.', 'employ~ tuyển dụng; capacity~ vị trí, khả năng; various ~ khác nhau, nhiều.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0015', 'pdf_database', 'The Department of Public Safety -------to a newly renovated facility at 200 Elm Drive, near Baker Rink, at the end of next month.', 'was relocated', 'to relocate', 'will relocate', 'relocated', 'C', 'Từ vựng: facility~ cơ sở; newly ~ mới, gần đây; relocate~ di dời.', 'Bộ An toàn Công cộng sẽ chuyển đến một cơ sở mới được cải tạo tại 200 Elm Drive, gần Baker Rink, vào cuối tháng tới.', 'facility~ cơ sở; newly ~ mới, gần đây; relocate~ di dời.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-01-b0016', 'pdf_database', 'Two years ago, some of the athletes ------- school to pursue a professional career or the Olympics.', 'leave', 'left', 'will leave', 'was left', 'B', 'Từ vựng: athlete~ vận động viên; pursue ~ theo đuổi; professional career~sự nghiệp chuyên nghiệp.', 'Hai năm trước, một số vận động viên rời trường để theo đuổi sự nghiệp chuyên nghiệp hoặc Thế vận hội.', 'athlete~ vận động viên; pursue ~ theo đuổi; professional career~sự nghiệp chuyên nghiệp.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0002', 'pdf_database', 'Ella Portofino, ------- is known for her motivational speeches, will be the guest speaker at ORIL Leadership Conference in June.', 'each', 'which', 'who', 'this', 'C', 'Từ vựng: be known for~được biết đến với; motivational speeches~ motivational speeches; guest speaker~ diễn giả khách mời;', 'Ella Portofino, người được biết đến với những bài phát biểu đầy động lực, sẽ là diễn giả khách mời tại Hội nghị Lãnh đạo ORIL vào tháng 6.', 'be known for~được biết đến với; motivational speeches~ motivational speeches; guest speaker~ diễn giả khách mời;') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0003', 'pdf_database', 'Journalists-------are registered for next Monday''s press conference will receive an admission pass upon registration.', 'whichever', 'whoever', 'who', 'whose', 'C', 'Từ vựng: journalist~ nhà báo; register~ đăng ký; press conference~ họp báo; admission pass~ thẻ vào cửa; upon registration~ khi đăng ký.', 'Các nhà báo được đăng ký cho cuộc họp báo vào thứ Hai tới sẽ nhận được một vé vào cửa khi đăng ký.', 'journalist~ nhà báo; register~ đăng ký; press conference~ họp báo; admission pass~ thẻ vào cửa; upon registration~ khi đăng ký.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0004', 'pdf_database', 'A fine of $200 will be imposed upon any drivers -------park illegally downtown during the holiday parade.', 'which', 'whose', 'whom', 'who', 'D', 'Từ vựng: fine ~ khoản phạt; impose~ áp dụng; illegally ~ trái phép; downtown ~ trung tâm thành phố; parade~ diễu hành.', 'Phạt tiền 200 đô la sẽ được áp dụng đối với bất kỳ tài xế nào đỗ xe trái phép trong trung tâm thành phố trong cuộc diễu hành ngày lễ.', 'fine ~ khoản phạt; impose~ áp dụng; illegally ~ trái phép; downtown ~ trung tâm thành phố; parade~ diễu hành.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0005', 'pdf_database', 'Saturday''s clearance sale will reduce old stock and make room for next season''s products, -------will arrive very soon.', 'when', 'what', 'where', 'which', 'D', 'Từ vựng: clearance sale~ đại hạ giá; reduce~ giảm; old stock~ hàng tồn kho cũ; make room for~ nhường chỗ.', 'Việc bán hàng đại hạ giá vào thứ Bảy sẽ giảm hàng tồn kho cũ và nhường chỗ cho các sản phẩm của mùa tiếp theo, cái mà sẽ đến rất sớm.', 'clearance sale~ đại hạ giá; reduce~ giảm; old stock~ hàng tồn kho cũ; make room for~ nhường chỗ.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0006', 'pdf_database', 'The opening remarks by Judge Yamamoto, ------- were devoted to international trade law, were the highlight of the conference.', 'who', 'which', 'what', 'whose', 'B', 'Từ vựng: opening remark~ bài phát biểu khai mạc; be devoted to~ dành cho; trade law~luật thương mại; highlight ~ điểm nổi bật.', 'Phát biểu khai mạc của Thẩm phán Yamamoto, cái mà được dành cho luật thương mại quốc tế, là điểm nổi bật của hội nghị.', 'opening remark~ bài phát biểu khai mạc; be devoted to~ dành cho; trade law~luật thương mại; highlight ~ điểm nổi bật.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0007', 'pdf_database', 'The Yunof brand of teas, -------entered the market in Norway only three years ago, is already among the top five best-selling brands.', 'when', 'who', 'where', 'which', 'D', 'Từ vựng: brand~ thương hiệu; enter~ đi vào; among~ trong số, giữa; best-selling~ bán chạy nhất.', 'Thương hiệu trà Yunof, cái mà đi vào thị trường Na Uy chỉ ba năm trước, đã nằm trong số năm thương hiệu bán chạy nhất.', 'brand~ thương hiệu; enter~ đi vào; among~ trong số, giữa; best-selling~ bán chạy nhất.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0008', 'pdf_database', 'There is now increased competition among motor-vehicle manufacturers ------- has resulted in better cars at lower prices.', 'those', 'where', 'that', '', 'C', 'Từ vựng: competition~ sự cạnh tranh; motor-vehicle ~ xe cơ giới; manufacturer~ nhà sản xuất; result in~ dẫn tới; lower prices~ giá cả thấp hơn.', 'Hiện nay có sự cạnh tranh gia tăng giữa các nhà sản xuất xe cơ giới, điều này dẫn đến những chiếc xe tốt hơn với giá thấp hơn.', 'competition~ sự cạnh tranh; motor-vehicle ~ xe cơ giới; manufacturer~ nhà sản xuất; result in~ dẫn tới; lower prices~ giá cả thấp hơn.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0009', 'pdf_database', 'Dr. Johnson is offering a three-hour workshop during -------she will share some perspectives on effective time management.', 'whose', 'while', 'whatever', 'which', 'D', 'Từ vựng: workshop~ hội thảo; during ~ trong suốt; perspective~ quan điểm; time management~ quản lý thời gian; effective ~ hiệu quả.', 'Tiến sĩ Johnson đang cung cấp một hội thảo kéo dài ba giờ, trong đó cô sẽ chia sẻ một số quan điểm về quản lý thời gian hiệu quả.', 'workshop~ hội thảo; during ~ trong suốt; perspective~ quan điểm; time management~ quản lý thời gian; effective ~ hiệu quả.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0010', 'pdf_database', 'New employees ------- wish to receive benefits should complete the necessary forms before the 10:00 A.M. orientation session.', 'whose', 'whom', 'who', 'which', 'C', 'Từ vựng: benefit~ trợ cấp; complete~ hoàn thành; necessary form~mẫu đơn cần thiết; orientation session~ phiên định hướng.', 'Nhân viên mới người mà muốn nhận trợ cấp nên hoàn thành các mẫu đơn cần thiết trước buổi định hướng 10:00 A.M.', 'benefit~ trợ cấp; complete~ hoàn thành; necessary form~mẫu đơn cần thiết; orientation session~ phiên định hướng.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0011', 'pdf_database', 'Ms. Reston and Mr. Parnthong were two of the senior partners -------visited the clients last week.', 'who', 'when', 'what', 'whose', 'A', 'Từ vựng: senior partner~ đối tác cao cấp; client~ khách hàng.', 'Bà Reston và ông Parnthong là hai trong số các đối tác cao cấp đã đến thăm khách hàng vào tuần trước.', 'senior partner~ đối tác cao cấp; client~ khách hàng.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0012', 'pdf_database', 'You may return for full credit any merchandise with ------- you are not satisfied.', 'who', 'what', 'which', 'whose', 'C', 'Từ vựng: return~ trả lại; credit ~tín dụng, tiền gửi; merchandise~ hàng hóa; satisfied with ~ hài lòng với.', 'Bạn có thể trả lại cho tín dụng đầy đủ bất kỳ hàng hóa mà bạn không hài lòng.', 'return~ trả lại; credit ~tín dụng, tiền gửi; merchandise~ hàng hóa; satisfied with ~ hài lòng với.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0013', 'pdf_database', 'The expert ------- spoke at last month''s seminar on environmental awareness has been nominated for a Flagler Prize.', 'whoever', 'when', 'wherever', 'who', 'D', 'Từ vựng: expert ~ chuyên gia; seminar~ hội thảo; environmental awareness ~ nhận thức về môi trường; nominate~ đề cử.', 'Chuyên gia phát biểu tại hội thảo tháng trước về nhận thức về môi trường đã được đề cử cho Giải thưởng Flagler.', 'expert ~ chuyên gia; seminar~ hội thảo; environmental awareness ~ nhận thức về môi trường; nominate~ đề cử.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0014', 'pdf_database', 'Be aware that candidates ------- applications are incomplete will not be considered for an interview.', 'who', 'whose', 'their', 'they', 'B', 'Từ vựng: Be aware that~ xin lưu ý rằng; candidate~ ứng cử viên; applications~ đơn xin việc; be considered for ~ được cân nhắc cho.', 'Xin lưu ý rằng các ứng viên có đơn đăng ký không đầy đủ sẽ không được xem xét cho một cuộc phỏng vấn.', 'Be aware that~ xin lưu ý rằng; candidate~ ứng cử viên; applications~ đơn xin việc; be considered for ~ được cân nhắc cho.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0015', 'pdf_database', 'Supervisors ------- have questions about the new expense report process should contact the budget office for assistance.', 'what', 'whose', 'which', 'who', 'D', 'Từ vựng: supervisor~ người giám sát; expense report ~ báo cáo chi phí; budget office~ phòng ngân sách; for assistance~ để được hỗ trợ.', 'Giám sát viên có câu hỏi về quy trình báo cáo chi phí mới nên liên hệ với văn phòng ngân sách để được hỗ trợ.', 'supervisor~ người giám sát; expense report ~ báo cáo chi phí; budget office~ phòng ngân sách; for assistance~ để được hỗ trợ.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0016', 'pdf_database', 'Award-winning Maida Stewart is one of the Australian artists ----- paintings are currently on display in the Dots exhibition at Pace Gallery.', 'who', 'whom', 'whoever', 'whose', 'D', 'Từ vựng: award-winning~ từng đoạt giải thưởng; artist~ nghệ sĩ; painting~ bức tranh; on display~ được trưng bày.', 'Maida Stewart người từng đoạt giải thưởng là một trong những họa sĩ người Úc có tranh hiện đang được trưng bày trong triển lãm Dots tại Pace Gallery.', 'award-winning~ từng đoạt giải thưởng; artist~ nghệ sĩ; painting~ bức tranh; on display~ được trưng bày.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0017', 'pdf_database', 'The head of human resources posted a list of all the employees ------- are supposed to be transferred to another department next week.', 'whose', 'who', 'where', 'when', 'B', 'Từ vựng: head ~ người đúng đầu; human resources ~ bộ phận nhân sự; be supposed to~ được cho là; transfer~ chuyển đổi; department ~ bộ phận.', 'Người đứng đầu bộ phận nhân sự đã đăng một danh sách tất cả các nhân viên được cho là sẽ được chuyển sang bộ phận khác vào tuần tới.', 'head ~ người đúng đầu; human resources ~ bộ phận nhân sự; be supposed to~ được cho là; transfer~ chuyển đổi; department ~ bộ phận.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0018', 'pdf_database', 'Employees ------- are experiencing technology-related problems may ask for help by placing a call to the IT team between 9 a.m. and 6 p.m.', 'who', 'whose', 'which', 'what', 'A', 'Từ vựng: experience ~ gặp phải, trải qua; technology-related problem~vấn đề liên quan đến công nghệ; ask for help~ yêu cầu trợ giúp; place a call ~ thực hiện cuộc gọi.', 'Nhân viên người mà đang gặp vấn đề liên quan đến công nghệ có thể yêu cầu trợ giúp bằng cách thực hiện cuộc gọi đến nhóm CNTT trong khoảng thời gian từ 9 giờ sáng đến 6 giờ chiều.', 'experience ~ gặp phải, trải qua; technology-related problem~vấn đề liên quan đến công nghệ; ask for help~ yêu cầu trợ giúp; place a call ~ thực hiện cuộc gọi.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0019', 'pdf_database', 'Antrix Cosmetics has announced that it will merge with Europe''s largest cosmetic firm, Beau & Chic, ------- will change both companies'' marketing strategies.', 'which', 'who', 'whose', 'what', 'A', 'Từ vựng: merge~ sáp nhập; cosmetic firm~ công ty mỹ phẩm; marketing strategy~ chiến lược tiếp thị.', 'Antrix Cosmetics đã thông báo rằng họ sẽ hợp nhất với công ty mỹ phẩm lớn nhất châu Âu, Beau & Chic, điều này sẽ thay đổi chiến lược tiếp thị của cả hai công ty.', 'merge~ sáp nhập; cosmetic firm~ công ty mỹ phẩm; marketing strategy~ chiến lược tiếp thị.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0020', 'pdf_database', 'The North East is one of the best regions in -------to start a new business, according to Business and Enterprise North East statistics.', 'what', 'which', 'where', 'whose', 'B', 'Từ vựng: region~ khu vực; according to~ theo; statistics~ thống kê.', 'Đông Bắc là một trong những khu vực tốt nhất để bắt đầu một doanh nghiệp mới, theo thống kê của Business and Enterprise North East.', 'region~ khu vực; according to~ theo; statistics~ thống kê.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0021', 'pdf_database', 'Eli Clare, -------latest book was published by Local Home Press, is nominated for the 2010 Lambda Literary Award.', 'whatever', 'whom', 'what', 'whose', 'D', 'Từ vựng: publish~ xuất bản; nominate~ được đề cử; Literary Award~ giả thưởng văn học.', 'Eli Clare, người mà cuốn sách mới nhất của bà ấy được xuất bản bởi Local Home Press, được đề cử cho Giải thưởng văn học Lambda 2010.', 'publish~ xuất bản; nominate~ được đề cử; Literary Award~ giả thưởng văn học.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0022', 'pdf_database', 'Nearly half of the customers -------responded to the survey said that Austraclear delivered services that were above their expectations.', 'who', 'whose', 'they', 'what', 'A', 'Từ vựng: nearly~ gần; respond to ~ trả lời; survey ~ khảo sát; deliver~ cung cấp, chuyển, giao; above expectations~ trên cả mong đợi.', 'Gần một nửa số khách hàng trả lời khảo sát nói rằng Austraclear cung cấp dịch vụ vượt quá mong đợi của họ.', 'nearly~ gần; respond to ~ trả lời; survey ~ khảo sát; deliver~ cung cấp, chuyển, giao; above expectations~ trên cả mong đợi.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-03-b0023', 'pdf_database', 'HIB Investment Bank, ------- shareholders were passionate about getting a new CEO, has been going through some chaotic changes recently.', 'whatever', 'whose', 'which', 'who', 'B', 'Từ vựng: shareholder~ cổ đông; passionate about ~thiết tha; go through~ trải qua, đi qua; chaotic~ hỗn loạn.', 'Ngân hàng đầu tư HIB, cái mà cổ đông của nó hào hứng về việc có được một CEO mới, đã trải qua một số thay đổi hỗn loạn gần đây.', 'shareholder~ cổ đông; passionate about ~thiết tha; go through~ trải qua, đi qua; chaotic~ hỗn loạn.') ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0001', 'pdf_database_entry', 'Trong cụm danh từ: "Successful candidates", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'candidates', 'Successful', 'success', 'assignment', 'A', 'Successful (adj) là tính từ bổ nghĩa cho danh từ chính ''candidates''.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0002', 'pdf_database_entry', 'Trong cụm danh từ: "Employees on international assignment", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'international', 'Employees', 'assignment', 'success', 'B', '''Employees'' là danh từ chính làm chủ ngữ; cụm ''on international assignment'' là giới từ bổ nghĩa.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0003', 'pdf_database_entry', 'Trong cụm danh từ: "A new production device", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'new', 'production', 'device', 'success', 'C', '''device'' là danh từ chính; ''A'' là mạo từ, ''new'' là tính từ, ''production'' là danh từ phụ đóng vai trò bổ nghĩa.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0004', 'pdf_database_entry', 'Trong cụm danh từ: "Department store managers", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'Department', 'store', 'success', 'managers', 'D', '''managers'' là danh từ chính; ''Department store'' là danh từ phụ bổ nghĩa.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0005', 'pdf_database_entry', 'Trong cụm danh từ: "All Seneca area residents who are required", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'residents', 'All', 'Seneca', 'area', 'A', '''residents'' là danh từ chính; ''All Seneca area'' bổ nghĩa phía trước, ''who are required'' là mệnh đề quan hệ bổ nghĩa phía sau.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0006', 'pdf_database_entry', 'Trong cụm danh từ: "Mr. Lee''s conciliatory comments", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'Mr', 'comments', 'Lee''s', 'conciliatory', 'B', '''comments'' là danh từ chính; ''Mr. Lee''s'' là sở hữu cách, ''conciliatory'' là tính từ bổ nghĩa.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0007', 'pdf_database_entry', 'Trong cụm danh từ: "Customers satisfied with the performance of their stereo equipment", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'satisfied', 'performance', 'Customers', 'their', 'C', '''Customers'' là danh từ chính; cụm ''satisfied with the performance...'' là mệnh đề tính ngữ rút gọn dạng quá khứ phân từ (P2).
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0008', 'pdf_database_entry', 'Trong cụm danh từ: "Patients wishing to reschedule their appointments", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'wishing', 'reschedule', 'their', 'Patients', 'D', '''Patients'' là danh từ chính; ''wishing to reschedule...'' là mệnh đề quan hệ rút gọn dạng hiện tại phân từ (V-ing).
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0009', 'pdf_database_entry', 'Trong cụm danh từ: "The decision to hire many additional employees", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'decision', 'hire', 'many', 'additional', 'A', '''decision'' là danh từ chính; ''The'' là mạo từ xác định, ''to hire many additional employees'' là cụm to-V bổ nghĩa mục đích.
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-04-q0010', 'pdf_database_entry', 'Trong cụm danh từ: "All visitors invited to the auto production plant", từ nào đóng vai trò là danh từ chính (Head Noun)?', 'All', 'visitors', 'invited', 'auto', 'B', '''visitors'' là danh từ chính; ''All'' là từ hạn định, ''invited to the auto production plant'' là cụm phân từ rút gọn bổ nghĩa.
