INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0003', 'pdf_database', 'Even if residents in the area have shown strong ------- to the project, the city government may not be hesitant to proceed with it.', 'resisting', 'resistant', 'resisted', 'resistance', 'D', NULL, 'Ngay cả khi cư dân trong khu vực đã thể hiện sự phản kháng mạnh mẽ đối với dự án, chính quyền thành phố có thể không ngần ngại tiến hành nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0004', 'pdf_database', 'According to many ------- of the industry, the majority of small-sized firms are hoping to enter into lucrative businesses.', 'survey', 'surveys', 'surveying', 'surveyed', 'B', NULL, 'Theo nhiều khảo sát của ngành, phần lớn các doanh nghiệp quy mô nhỏ đang hy vọng tham gia vào các doanh nghiệp sinh lợi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
