INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0006', 'pdf_database', 'You should provide the requested ------- when submitting advertising proposals since incomplete ones will not be accepted.', 'information', 'inform', 'informing', 'informed', 'A', NULL, 'Bạn nên cung cấp thông tin được yêu cầu khi gửi đề xuất quảng cáo vì những đề xuất không đầy đủ sẽ không được chấp nhận.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0007', 'pdf_database', 'All of Molina Language lnstitute''s ------- have three or more years of experience and a valid teaching credential.', 'instructed', 'instruction', 'instructing', 'instructors', 'D', NULL, 'Tất cả những người hướng dẫn của Molina Language lnstolarship đều có ba năm kinh nghiệm trở lên và chứng chỉ giảng dạy hợp lệ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0008', 'pdf_database', 'Much of the expected boost in revenue is related to a transaction tax which has yet to receive final ------- from Congress.', 'approving', 'approved', 'approval', 'approves', 'C', NULL, 'Phần lớn việc tăng được dự kiến trong doanh thu có liên quan đến thuế giao dịch cái mà vẫn chưa nhận được sự chấp thuận cuối cùng từ Quốc hội.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0009', 'pdf_database', 'You should include include your ------- in every letter you send to customers, which helps remind them of whom they do business with.', 'signing', 'signed', 'signature', 'to sign', 'C', NULL, 'Bạn nên bao gồm chữ ký của mình trong mỗi thư bạn gửi cho khách hàng, điều này giúp nhắc nhở họ về việc họ hợp tác với ai.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0010', 'pdf_database', '------- for reconstruction contracts has been getting stiffer over the years since it can generate enormously lucrative earnings.', 'Competitively', 'Competition', 'Competitive', 'Competes', 'B', NULL, 'Cạnh tranh cho các hợp đồng tái xây dựng đã trở nên khó khăn hơn trong những năm qua vì nó có thể tạo ra thu nhập cực kỳ sinh lợi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0011', 'pdf_database', 'When the ------- for this new safety policy was under consideration by the managers, a number of experts were asked for their comments.', 'proposing', 'propose', 'proposes', 'proposal', 'D', NULL, 'Khi đề xuất cho chính sách an toàn mới này được các nhà quản lý xem xét, một số chuyên gia đã được hỏi ý kiến của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0012', 'pdf_database', 'We are proud to announce their upcoming ------- in an event whose purpose is to educate attendees on e-mail management tools.', 'participation', 'participated', 'participating', 'participate', 'A', NULL, 'Chúng tôi tự hào thông báo sự tham gia sắp tới của họ trong một sự kiện với mục đích giáo dục người tham dự về các công cụ quản lý e-mail.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0013', 'pdf_database', 'This letter is to solicit -------of candidates to be considered for the vacant positions in sales that should be filled right away.', 'nominate', 'nominations', 'nominating', 'nominated', 'B', NULL, 'Bức thư này là để kêu gọi các đề cử của các ứng cử viên được xem xét cho các vị trí còn trống trong doanh số cần được điền ngay.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0014', 'pdf_database', 'The newly launched cell phones were designed to deliver exceptional ------- in various functions.', 'performing', 'performed', 'perform', 'performance', 'D', NULL, 'Các điện thoại di động mới được ra mắt được thiết kế để cung cấp hiệu suất đặc biệt trong các chức năng khác nhau.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0015', 'pdf_database', 'Due to his impressive -------and experience, Rajan was offered interviews with three of Australia''s top food companies.', 'qualified', 'qualifies', 'qualifications', 'qualifying', 'C', NULL, 'Do trình độ và kinh nghiệm ấn tượng của mình, Rajan đã được mời phỏng vấn ba công ty thực phẩm hàng đầu của Úc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0016', 'pdf_database', 'We regularly monitor the quality of products and services in order to meet strict -------.', 'require', 'requiring', 'required', 'requirements', 'D', NULL, 'Chúng tôi thường xuyên theo dõi chất lượng sản phẩm và dịch vụ để đáp ứng các yêu cầu nghiêm ngặt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0017', 'pdf_database', 'The conference''s keynote speaker called this morning for -------that everything has been set for his presentation.', 'confirm', 'confirming', 'confirmation', 'confirmed', 'C', NULL, 'Diễn giả chính của hội nghị đã gọi sáng nay để xác nhận rằng mọi thứ đã được thiết lập cho bài thuyết trình của ông.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0018', 'pdf_database', 'To demonstrate our appreciation to our valued -------,we are offering free tickets to new plays which received outstanding reviews from critics.', 'custom', 'customary', 'customers', 'customized', 'C', NULL, 'Để thể hiện sự đánh giá cao của chúng tôi đối với các khách hàng quan trọng của mình, chúng tôi đang cung cấp vé miễn phí cho các vở kịch mới cái mà nhận được đánh giá xuất sắc từ các nhà phê bình.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
