INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0020', 'pdf_database', 'Our monthly production capability is expected to grow significantly, owing to the ------- of our own factories in China.', 'expand', 'expands', 'expansion', 'expansive', 'C', NULL, 'Khả năng sản xuất hàng tháng của chúng tôi dự kiến sẽ tăng đáng kể, nhờ vào việc mở rộng các nhà máy của chúng tôi tại Trung Quốc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0021', 'pdf_database', 'At the same time, the company also won a two-million-dollar-------for maintenance of the trains for the next seven years.', 'contract', 'contracts', 'contracted', 'contracting', 'A', NULL, 'Đồng thời, công ty cũng giành được hợp đồng trị giá hai triệu đô la để bảo trì các đoàn tàu trong bảy năm tiếp theo.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0022', 'pdf_database', 'Your new coffee machine comes with detailed -------which will help you use it more effectively.', 'instruct', 'instructing', 'instructions', 'instructional', 'C', NULL, 'Máy pha cà phê mới của bạn đi kèm với các hướng dẫn chi tiết sẽ giúp bạn sử dụng nó hiệu quả hơn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0023', 'pdf_database', 'Ami Natashi not only remained but received a -------just two weeks after the company reduced its staff by 10 percent.', 'promotion', 'promotes', 'promoted', 'promoting', 'A', NULL, 'Ami Natashi không chỉ ở lại mà còn nhận được sự thăng chức chỉ hai tuần sau khi công ty giảm 10% nhân viên.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-06-b0024', 'pdf_database', 'The Silo House Restaurant will also be open this weekend, but anyone wanting to eat there should make ------- to ensure a seat.', 'reserving', 'reservations', 'reserve', 'reserved', 'B', NULL, 'Nhà hàng Silo House cũng sẽ mở cửa vào cuối tuần này, nhưng bất cứ ai muốn ăn ở đó nên đặt chỗ trước để đảm bảo chỗ ngồi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
