INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0022', 'pdf_database', 'Pioneer Steel guarantees that all information gathered through this website is strictly -------and used only by Pioneer Steel.', 'confide', 'confides', 'confidential', 'confidentially', 'C', NULL, 'Pioneer Steel đảm bảo rằng tất cả thông tin được thu thập thông qua trang web này được bảo mật tuyệt đối và chỉ được sử dụng bởi Pioneer Steel.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
