INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0024', 'pdf_database', 'The TIPH employees are -------by their distinctive khaki uniforms and the special emblem on their uniforms and vehicles.', 'identify', 'identifies', 'identity', 'identifiable', 'D', NULL, 'Nhân viên của TIPH có thể được nhận dạng bằng đồng phục kaki đặc biệt và biểu tượng đặc biệt trên đồng phục và xe cộ của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0025', 'pdf_database', 'Since he joined our company in 2006, Mr. Ogawa has proven himself to be a very -------employee.', 'valuably', 'valuable', 'valuing', 'value', 'B', NULL, 'Kể từ khi gia nhập công ty chúng tôi vào năm 2006, ông Ogawa đã chứng tỏ mình là một nhân viên rất có giá trị.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0026', 'pdf_database', 'Elizabeth Farnsworth will lead a discussion with a -------group of voters in Denver on their views of the upcoming presidential election.', 'diverse', 'diversity', 'diversely', 'diversify', 'A', NULL, 'Elizabeth Farnsworth sẽ dẫn đầu một cuộc thảo luận với một nhóm cử tri đa dạng ở Denver về quan điểm của họ về cuộc bầu cử tổng thống sắp tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0027', 'pdf_database', 'Mr. Colin Johnston is a principal research scientist working on ------- techniques for the remediation of contaminated groundwater environments.', 'innovate', 'innovative', 'innovates', 'innovatively', 'B', NULL, 'Ông Colin Johnston là một nhà khoa học nghiên cứu chính làm việc về các kỹ thuật sáng tạo để khắc phục môi trường nước ngầm bị ô nhiễm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0028', 'pdf_database', 'Travel expenses should be ------- no later than 30 calendar days after returning from a business trip.', 'submit', 'submits', 'submitted', 'submissions', 'C', NULL, 'Chi phí đi lại nên được gửi không muộn hơn 30 ngày theo lịch sau khi trở về từ chuyến công tác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0029', 'pdf_database', 'It is common practice for a firm to seek a ------- advantage in order to maintain its position in the marketplace.', 'compete', 'competition', 'competitive', 'competitively', 'C', NULL, 'Việc tìm kiếm một lợi thế cạnh tranh để duy trì vị thế của mình trên thị trường là thực tế phổ biến đối với một công ty.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0031', 'pdf_database', 'The enclosed documents summarize ------- changes to the existing overtime regulations.', 'propose', 'proposed', 'proposes', 'proposing', 'B', NULL, 'Các tài liệu được đính kèm tóm tắt các thay đổi được đề xuất đối với các quy định làm thêm giờ hiện có.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0032', 'pdf_database', 'All the terms of the agreement must be clear so that the meaning and intent won''t be ------- by either party.', 'misinterpret', 'misinterpretation', 'misinterpreted', 'misinterpreting', 'C', NULL, 'Tất cả các điều khoản của thỏa thuận phải rõ ràng để ý nghĩa và mục đích sẽ không bị hiểu sai bởi một trong hai bên.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0033', 'pdf_database', 'Some visitors to Dubrovnik feel that it is too -------with tourists to be enjoyable during the summer.', 'crowd', 'crowds', 'crowding', 'crowded', 'D', NULL, 'Một số du khách đến Dubrovnik cảm thấy rằng nó quá đông khách du lịch để vui chơi trong mùa hè.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0034', 'pdf_database', 'Although some studies report different effects of overtime work, they are ----- with respect to productivity levels.', 'comparing', 'comparable', 'compare', 'compares', 'B', NULL, 'Mặc dù một số nghiên cứu báo cáo các tác động khác nhau của việc làm thêm giờ, chúng có thể so sánh với mức năng suất.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0035', 'pdf_database', 'Applicants who possess interpersonal skills and strong analytical skills to gather and analyze information for reports will be especially -------.', 'prefer', 'preferred', 'preferable', 'preferring', 'B', NULL, 'Các ứng viên có kỹ năng giao tiếp cá nhân và kỹ năng phân tích tốt để thu thập và phân tích thông tin cho các báo cáo sẽ được đặc biệt ưu tiên.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0036', 'pdf_database', 'After ------- requests by residents, the city''s board members decided to install additional traffic lights.', 'repeat', 'repeated', 'repeating', 'repetition', 'B', NULL, 'Sau những yêu cầu được lặp lại của cư dân, các thành viên hội đồng thành phố quyết định lắp đặt thêm đèn giao thông.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0037', 'pdf_database', 'One of the most -------consequences of worldwide climate change is the steady rise of sea levels.', 'worry', 'worrying', 'worried', 'worries', 'B', NULL, 'Một trong những hậu quả đáng lo ngại nhất của biến đổi khí hậu trên toàn thế giới là mực nước biển dâng cao.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0038', 'pdf_database', 'We are planning to implement a -------paper-recycling program for all branch offices effective next month.', 'revising', 'revision', 'revise', 'revised', 'D', NULL, 'Chúng tôi đang lên kế hoạch thực hiện chương trình tái chế giấy được sửa đổi cho tất cả các văn phòng chi nhánh có hiệu lực vào tháng tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0039', 'pdf_database', 'The event was well -------and covered by numerous media including television stations and newspapers across the country.', 'publicizing', 'publicized', 'publicity', 'publicize', 'B', NULL, 'Sự kiện này đã được công bố rộng rãi và được phủ sóng bởi nhiều phương tiện truyền thông bao gồm các đài truyền hình và báo chí trên cả nước.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0040', 'pdf_database', 'As the largest dealer in the state, Auto Fair maintains an -------inventory of new vehicles for immediate delivery.', 'impress', 'impressive', 'impressively', 'impressed', 'B', NULL, 'Là đại lý lớn nhất trong tiểu bang, Auto Fair duy trì một kho hàng ấn tượng về các phương tiện mới cho việc giao hàng ngay lập tức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0041', 'pdf_database', 'If, for any reason, you are not going to make your-------travel plans, please call us at 800-347-5633.', 'scheduling', 'scheduler', 'scheduled', 'schedule', 'C', NULL, 'Nếu vì bất kỳ lý do gì, bạn sẽ không lập kế hoạch du lịch theo lịch trình của mình, vui lòng gọi cho chúng tôi theo số 800-347-5633.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0042', 'pdf_database', 'Because of his outstanding work, Mr. Tianfu Yang has been highly-------for the position of marketing director by the board of directors.', 'recommended', 'recommendation', 'recommend', 'recommending', 'A', NULL, 'Vì công việc xuất sắc của mình, ông Tianfu Yang đã được ban giám đốc đánh giá cao cho vị trí giám đốc tiếp thị.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0043', 'pdf_database', 'Ms. Jespersen is------- to accept your invitation to become a member of the Washington Community Reinvestment Association.', 'pleasure', 'please', 'pleasing', 'pleased', 'D', NULL, 'Bà Jespersen vui mừng nhận lời mời trở thành thành viên của Hiệp hội Tái đầu tư Cộng đồng Washington.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0044', 'pdf_database', 'The annual NCA Conference will be held at the newly ------- Hilton Wilmington Hotel located in the heart of Wilmington.', 'renovate', 'renovated', 'renovating', 'renovation', 'B', NULL, 'Hội nghị NCA hàng năm sẽ được tổ chức tại khách sạn Hilton Wilmington mới được cải tạo lại nằm ở trung tâm của Wilmington.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0045', 'pdf_database', 'The loading dock entrance is accessible from the South Town Exposition Center''s parking lot and is------- on the east side of the building.', 'locates', 'located', 'locating', 'was locating', 'B', NULL, 'Lối vào bến tàu có thể truy cập từ bãi đậu xe của Trung tâm Triển lãm South Town và nằm ở phía đông của tòa nhà.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0046', 'pdf_database', 'The new business plan does not necessarily need to contain a -------marketing plan.', 'detail', 'details', 'detailed', 'detailing', 'C', NULL, 'Kế hoạch kinh doanh mới không nhất thiết phải chứa một kế hoạch tiếp thị chi tiết.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0047', 'pdf_database', 'Even though we spent millions of dollars on marketing and advertising, sales of our new product have been ------- .', 'disappointed', 'disappointment', 'disappoint', 'disappointing', 'D', NULL, 'Mặc dù chúng tôi đã chi hàng triệu đô la cho tiếp thị và quảng cáo, doanh số bán sản phẩm mới của chúng tôi vẫn đáng thất vọng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0048', 'pdf_database', 'After 15 years as a fashion designer, Mr. Jacobs will quit his job to pursue an -------career in public relations.', 'excite', 'excited', 'have excited', 'exciting', 'D', NULL, 'Sau 15 năm làm nhà thiết kế thời trang, ông Jacobs sẽ từ bỏ công việc để theo đuổi sự nghiệp thú vị trong quan hệ công chúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0049', 'pdf_database', 'Of all the people who submitted a resume, Mr. Bacon has the most-------cover letter.', 'impress', 'impression', 'impressed', 'impressive', 'D', NULL, 'Trong tất cả những người nộp hồ sơ xin việc, ông Bacon có thư xin việc ấn tượng nhất.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0050', 'pdf_database', 'The -------booklet contains information regarding services that are available through Harpers Cleaning Service.', 'enclose', 'enclosed', 'enclosure', 'enclosing', 'B', NULL, 'Tập sách được đính kèm chứa thông tin liên quan đến các dịch vụ có sẵn thông qua Dịch vụ dọn dẹp Harpers.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
