INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0053', 'pdf_database', 'Working so many hours of overtime to meet the deadline has left the design staff feeling -------.', 'exhaust', 'exhausted', 'exhausting', 'exhaustive', 'B', NULL, 'Làm việc quá nhiều giờ để đáp ứng thời hạn đã khiến nhân viên thiết kế cảm thấy kiệt sức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0054', 'pdf_database', 'In March, the Grand Symphony Orchestra will present an ------ opera by talented newcomer Maria Cruz.', 'excite', 'excites', 'excited', 'exciting', 'D', NULL, 'Vào tháng 3, Dàn nhạc Giao hưởng Grand sẽ trình bày một vở nhạc kịch thú vị của nghệ sĩ mới tài năng Maria Cruz.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0055', 'pdf_database', 'Payment is -------at the time you check out of the conference center.', 'expect', 'expecting', 'expected', 'expectation', 'C', NULL, 'Thanh toán được dự kiến tại thời điểm bạn trả phòng trung tâm hội nghị.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0056', 'pdf_database', 'Customers may return any item within 30 days if they are not ------ with their purchase.', 'satisfactory', 'satisfaction', 'satisfied', 'satisfy', 'C', NULL, 'Khách hàng có thể trả lại bất kỳ mặt hàng nào trong vòng 30 ngày nếu họ không hài lòng với giao dịch mua hàng của mình.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0057', 'pdf_database', 'Our chief operating officer was very ------ by the latest sales figures.', 'impress', 'impressing', 'impressed', 'impressive', 'C', NULL, 'Giám đốc điều hành của chúng tôi đã rất ấn tượng bởi những con số bán hàng mới nhất.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
