INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0060', 'pdf_database', 'Customers with concerns about the safety of the product are advised to call the -------as soon as possible.', 'manufacture', 'manufacturing', 'manufacturer', 'manufactured', 'C', NULL, 'Khách hàng có mối quan tâm về sự an toàn của sản phẩm nên gọi cho nhà sản xuất càng sớm càng tốt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0061', 'pdf_database', 'Tonight''s performance is -------to raise awareness about our city''s urban renewal initiative.', 'intend', 'intended', 'intention', 'intentional', 'B', NULL, 'Buổi biểu diễn tối nay nhằm nâng cao nhận thức về sáng kiến cải tạo đô thị của thành phố chúng ta.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0062', 'pdf_database', 'The -------outlay of assets for the construction of the new streetcar lanes has been cited by newspapers as the main cause of the project''s dismissal.', 'initially', 'initiate', 'initiation', 'initial', 'D', NULL, 'Việc chi tiêu ban đầu của tài sản cho việc xây dựng làn đường xe điện mới đã được các tờ báo trích dẫn là nguyên nhân chính của việc loại bỏ dự án.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0063', 'pdf_database', 'While the engineering team''s -------has improved, overall productivity has been in a noticeable decline for the past three years.', 'motivate', 'motives', 'motivational', 'motivation', 'D', NULL, 'Trong khi động lực của nhóm kỹ sư đã được cải thiện, thì năng suất tổng thể đã giảm đáng kể trong ba năm qua.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0064', 'pdf_database', 'At yesterday''s meeting, staff members were introduced to Peter McCabe, the recently ------- manager of the Dynasty Hotel in Washington D.C.', 'appointing', 'appointment', 'appoint', 'appointed', 'D', NULL, 'Trong cuộc họp ngày hôm qua, các nhân viên đã được giới thiệu với Peter McCabe, người quản lý mới được bổ nhiệm của Khách sạn Dynasty tại Washington D.C.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0065', 'pdf_database', 'This year''s excellent ------- has earned our production plant renown in the company.', 'performed', 'performable', 'performance', 'perform', 'C', NULL, 'Hiệu suất tuyệt vời trong năm nay đã giúp nhà máy sản xuất của chúng tôi nổi tiếng trong công ty.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0066', 'pdf_database', 'The primary -------concern among our manufacturers is acquiring the necessary resources at a reasonable price.', 'finances', 'financed', 'financial', 'financially', 'C', NULL, 'Mối quan tâm tài chính chủ yếu giữa các nhà sản xuất của chúng tôi là có được các nguồn lực cần thiết với giá cả hợp lý.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0067', 'pdf_database', 'Questions about production concerns should be -------to Ms. Helen Yan.', 'direction', 'director', 'directs', 'directed', 'D', NULL, 'Câu hỏi về mối quan tâm sản xuất nên được gửi đến bà Helen Yan.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0068', 'pdf_database', 'Our firm received -------from numerous clients for our excellent work over the past twenty years.', 'compliment', 'complimented', 'compliments', 'complimentary', 'C', NULL, 'Công ty chúng tôi đã nhận được lời khen từ nhiều khách hàng cho công việc tuyệt vời của chúng tôi trong hai mươi năm qua.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0069', 'pdf_database', 'Ms. Julie Kennedy and her innovative marketing team have gained renown for creating ------- products for struggling companies.', 'promote', 'promotes', 'promotion', 'promotional', 'D', NULL, 'Bà Julie Kennedy và đội ngũ tiếp thị sáng tạo của bà đã có được sự nổi tiếng vì đã tạo ra các sản phẩm quảng cáo cho các công ty đang gặp khó khăn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0070', 'pdf_database', 'Sea Sapphire Cruises is -------to announce the launch of their newest luxury ocean liner.', 'pleased', 'pleasant', 'pleasure', 'pleasing', 'A', NULL, 'Sea Sapphire Cruises vui mừng thông báo ra mắt tàu biển sang trọng mới nhất của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0071', 'pdf_database', 'Sales-------are encouraged to familiarize themselves with the location of various merchandise in the department store.', 'representational', 'represent', 'represents', 'representatives', 'D', NULL, 'Đại diện bán hàng được khuyến khích làm quen với vị trí của hàng hóa khác nhau trong cửa hàng bách hóa.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0072', 'pdf_database', 'The manager, Mr. Farthing, and his assistant, Mr. Donahue, conducted an -------inventory check this weekend.', 'impressive', 'impressively', 'impression', 'impressiveness', 'A', NULL, 'Người quản lý, ông Farthing, và trợ lý của ông, ông Donahue, đã tiến hành kiểm tra hàng tồn kho ấn tượng vào cuối tuần này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0073', 'pdf_database', 'If you did not receive -------for your order, please contact us at the customer service department.', 'authorize', 'authorized', 'authorization', 'authoritative', 'C', NULL, 'Nếu bạn không nhận được ủy quyền cho đơn đặt hàng của mình, vui lòng liên hệ với chúng tôi tại bộ phận dịch vụ khách hàng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0074', 'pdf_database', 'Fruit Mart''s advertising initiative has been the most -------marketing project in our neighborhood.', 'persuasive', 'persuasively', 'persuade', 'persuasion', 'A', NULL, 'Sáng kiến quảng cáo của Fruit Mart là dự án tiếp thị thuyết phục nhất trong khu phố của chúng tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0075', 'pdf_database', 'She has very high -------for her new job, although she has only been there for a week.', 'expected', 'expecting', 'expectedly', 'expectations', 'D', NULL, 'Cô ấy có kỳ vọng rất cao cho công việc mới của mình, mặc dù cô ấy chỉ mới ở đó được một tuần.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0076', 'pdf_database', 'Regulations have been enacted to ensure that labels on all medications are easily -----.', 'understand', 'understanding', 'understandably', 'understandable', 'D', NULL, 'Các quy định đã được ban hành để đảm bảo rằng nhãn trên tất cả các loại thuốc đều dễ hiểu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
