INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0101', 'pdf_database', 'Mr. Corbett mentioned at last week''s meeting the difference in finances this year compared to the -------quarter last year.', 'compare', 'comparable', 'comparison', 'comparatively', 'B', NULL, 'Ông Corbett đã đề cập tại cuộc họp tuần trước về sự khác biệt về tài chính trong năm nay so với quý tương đương năm ngoái.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0102', 'pdf_database', 'As the chief administrative officer, Quincy Paxton will face exciting ------- in this new job with Laval International Shipping Company.', 'challenge', 'challenges', 'challenging', 'challenged', 'B', NULL, 'Là giám đốc hành chính, Quincy Paxton sẽ đối mặt với những thách thức thú vị trong công việc mới này với Công ty Vận tải Quốc tế Laval.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
