INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0105', 'pdf_database', 'Once you have your resume with references and -------, please submit it to the Human Resources Department on the 3rd floor.', 'qualified', 'qualifications', 'qualify', 'qualifying', 'B', NULL, 'Khi bạn có sơ yếu lý lịch của bạn với các giấy chứng nhận và văn bằng, xin vui lòng gửi nó cho Phòng Nhân sự trên tầng 3.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0106', 'pdf_database', 'Whether it is -------to register for a student discount card depends on the needs of the individual.', 'necessary', 'necessarily', 'necessitate', 'necessity', 'A', NULL, 'Liệu rằng có cần thiết phải đăng ký thẻ giảm giá sinh viên hay không tùy thuộc vào nhu cầu của từng người.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0107', 'pdf_database', 'The -------of a discount department store was delayed by the protests of several members of the community.', 'construct', 'constructive', 'construction', 'constructed', 'C', NULL, 'Việc xây dựng một cửa hàng bách hóa giảm giá đã bị trì hoãn bởi sự phản đối của một số thành viên của cộng đồng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0108', 'pdf_database', 'One of the -------international research facilities in botany is located at the Hoskin Museum of Natural History.', 'led', 'leads', 'leader', 'leading', 'D', NULL, 'Một trong những cơ sở nghiên cứu quốc tế hàng đầu về thực vật học được đặt tại Bảo tàng Lịch sử Tự nhiên Hoskin.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0109', 'pdf_database', 'Ms. Richards has been an exceptionally ------- member of the marketing team, providing Billingsgate Enterprises with great service for nine years.', 'energy', 'energize', 'energetic', 'energetically', 'C', NULL, 'Bà Richards đã là một thành viên năng nổ đặc biệt của nhóm tiếp thị, cung cấp cho Billingsgate Enterprises sự phục vụ tuyệt vời trong chín năm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0110', 'pdf_database', 'The loss of our foreign manufacturing plants may be a ------- outcome of the new plans being implemented.', 'probable', 'probability', 'probably', 'probabilities', 'A', NULL, 'Việc mất các nhà máy sản xuất nước ngoài của chúng tôi có thể là kết quả có thể xảy ra của những kế hoạch mới đang được thực hiện.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0111', 'pdf_database', 'Rosalind Media Ltd. came up with the idea to hire artists to create ------- artworks for the purpose of marketing.', 'originator', 'original', 'originally', 'originality', 'B', NULL, 'Rosalind Media Ltd. đã nảy ra ý tưởng thuê các nghệ sĩ để tạo ra các tác phẩm nghệ thuật gốc/nguyên bản cho mục đích tiếp thị.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0112', 'pdf_database', 'The -------of Mr. Alex Hartham was to initiate a merger with Culford International.', 'intention', 'intended', 'intentional', 'intending', 'A', NULL, 'Ý định của ông Alex Hartham là bắt đầu một sự sáp nhập với Culford International.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0113', 'pdf_database', 'Under the -------of Dr. Veracini, Cascadia Chamicals Inc. has patented several formulas and signed some lucrative contracts with other companies.', 'directs', 'directed', 'direction', 'directly', 'C', NULL, 'Dưới sự chỉ đạo của Tiến sĩ Veracini, Cascadia Chamicals Inc. đã cấp bằng sáng chế cho một số công thức và ký một số hợp đồng sinh lợi với các công ty khác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0114', 'pdf_database', 'Graduates from the Melrose College of Technology often make -------contributions in several fields, including engineering, computer sciences, and astronomy.', 'value', 'valuable', 'valuably', 'valuing', 'B', NULL, 'Sinh viên tốt nghiệp từ Đại học Công nghệ Melrose thường có những đóng góp có giá trị trong một số lĩnh vực, bao gồm kỹ thuật, khoa học máy tính và thiên văn học.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-07-b0115', 'pdf_database', 'The -------delivery date was moved ahead by one week because of a minor computer error.', 'expected', 'expecting', 'expectation', 'expect', 'A', NULL, 'Ngày giao hàng dự kiến đã được dời trước một tuần vì một lỗi máy tính nhỏ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0002', 'pdf_database', 'Mr. Garry Noxon in accounting was -------warned about having too many numerical errors in the budget report.', 'repeat', 'repeatedly', 'repeater', 'repetition', 'B', NULL, 'Ông Garry Noxon ở bộ phận kế toán đã nhiều lần được cảnh báo về việc có quá nhiều lỗi liên quan đến con số trong báo cáo ngân sách.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0003', 'pdf_database', 'You can ------- rebuild your credit by taking steps to repair your credit rating as soon as possible.', 'easy', 'easier', 'easily', 'easiness', 'C', NULL, 'Bạn có thể dễ dàng xây dựng (làm lại) thẻ lại tín dụng của mình bằng cách thực hiện các bước để sửa xếp hạng tín dụng của bạn càng sớm càng tốt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0004', 'pdf_database', 'The elegant hotel known for its fabulous amenities is ------- located near the local airport.', 'convenience', 'convenient', 'conveniently', 'conveniences', 'C', NULL, 'Khách sạn thanh lịch được biết đến với các tiện nghi tuyệt vời nằm ở vị trí thuận tiện gần sân bay địa phương.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0005', 'pdf_database', 'Many financial specialists ------- predicted that industries might encounter a decline in manufacturing investment in 2007 by almost 15 percent.', 'mistook', 'mistake', 'mistaken', 'mistakenly', 'D', NULL, 'Nhiều chuyên gia tài chính dự đoán nhầm rằng các ngành công nghiệp có thể gặp phải sự suy giảm đầu tư sản xuất trong năm 2007 gần 15%.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0006', 'pdf_database', 'Our experienced and skilled technicians can be of much help in the event that you ------- delete something essential from the program.', 'accident', 'accidental', 'accidents', 'accidentally', 'D', NULL, 'Kỹ thuật viên giàu kinh nghiệm và có tay nghề cao của chúng tôi có thể giúp đỡ rất nhiều trong trường hợp bạn vô tình xóa một cái gì đó thiết yếu (quan trọng) khỏi chương trình.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0007', 'pdf_database', 'All the workers are required to -------verify that the proper maintenance of storage facilities is conducted with extreme care.', 'periodic', 'periodical', 'periodically', 'period', 'C', NULL, 'Tất cả các công nhân được yêu cầu xác minh định kỳ rằng việc bảo trì đúng cách các thiết bị lưu trữ được tiến hành hết sức cẩn thận.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0008', 'pdf_database', 'The president of Kasara Inc. ------- announced that Lopez Davis, who has served the company for more than 30 years, would retire at the end of next month.', 'regretting', 'regretted', 'regretfully', 'regretful', 'C', NULL, 'Chủ tịch của Kasara Inc. đã tiếc nuối tuyên bố rằng Lopez Davis, người đã phục vụ công ty trong hơn 30 năm, sẽ nghỉ hưu vào cuối tháng tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0009', 'pdf_database', 'Road and street signs must be ------- visible even in the distance in order for drivers to know where they are heading.', 'clearness', 'clear', 'clearly', 'clearest', 'C', NULL, 'Biển báo đường và đường phố phải được nhìn thấy rõ ngay cả ở khoảng cách xa để tài xế biết họ đang đi đâu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0010', 'pdf_database', 'Once invoices arrive in the office, they should be processed -------- in order to maintain accurate records.', 'prompt', 'promptly', 'promptness', 'more prompt', 'B', NULL, 'Khi hóa đơn đến văn phòng, chúng cần được xử lý ngay lập tức để duy trì hồ sơ chính xác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0011', 'pdf_database', 'The medications widely used for patients should be -------evaluated for long-term use.', 'rigor', 'rigors', 'rigorous', 'rigorously', 'D', NULL, 'Các loại thuốc được sử dụng rộng rãi cho bệnh nhân nên được đánh giá nghiêm ngặt để sử dụng lâu dài.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0012', 'pdf_database', 'Events in celebration of our 10th anniversary will begin ------- at 1 O A.M. tomorrow morning.', 'precise', 'precision', 'precisely', 'preciseness', 'C', NULL, 'Các sự kiện trong lễ kỷ niệm 10 năm của chúng tôi sẽ bắt đầu chính xác vào lúc 1 O A.M. sáng mai.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0013', 'pdf_database', 'Please note that payment statements must be addressed -------to the recipients.', 'correct', 'correcting', 'correction', 'correctly', 'D', NULL, 'Xin lưu ý rằng báo cáo thanh toán phải được giải quyết chính xác cho người nhận.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0014', 'pdf_database', 'Lonan Imports will work-------with any distributor to fulfill a customer request.', 'directly', 'directs', 'directed', 'directness', 'A', NULL, 'Lonan Imports sẽ làm việc trực tiếp với bất kỳ nhà phân phối nào để thực hiện yêu cầu của khách hàng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0015', 'pdf_database', 'Grove Canoes'' prices may-------vary depending on changes in the cost of raw materials.', 'occasion', 'occasions', 'occasional', 'occasionally', 'D', NULL, 'Giá của Cano Grove đôi khi có thể thay đổi tùy thuộc vào thay đổi về chi phí nguyên liệu thô.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0016', 'pdf_database', 'Visitors to the library are asked to speak-------and keep conversations brief when in the main reading room.', 'quiet', 'quietly', 'quietest', 'quietness', 'B', NULL, 'Khách đến thư viện được yêu cầu nói chuyện nhỏ nhẹ và nói ngắn gọn khi ở trong phòng đọc chính.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0017', 'pdf_database', 'Most of the new houses for sale on Seegers Island are -------priced and in excellent condition.', 'moderate', 'moderated', 'moderately', 'moderation', 'C', NULL, 'Hầu hết các ngôi nhà mới để bán trên đảo Seegers có giá vừa phải và trong tình trạng tuyệt vời.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0018', 'pdf_database', 'The board of trustees will -------vote on the revised proposal at its meeting later this month.', 'define', 'definite', 'definitive', 'definitely', 'D', NULL, 'Hội đồng quản trị chắc chắn sẽ bỏ phiếu về đề xuất sửa đổi tại cuộc họp vào cuối tháng này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0019', 'pdf_database', 'Unlike traditional book publishers, P-Gram Books focuses -------on producing audio books that can be downloaded from the Internet.', 'exclusively', 'exclusive', 'exclusives', 'exclusivity', 'A', NULL, 'Không giống như các nhà xuất bản sách truyền thống, P-Gram Books tập trung hoàn toàn vào việc sản xuất sách âm thanh có thể tải xuống từ Internet.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0020', 'pdf_database', 'Aliflora, Inc., grows fifty varieties of roses -------and is now the second largest exporter in the region.', 'commerce', 'commercial', 'commercially', 'commercials', 'C', NULL, 'Aliflora, Inc., trồng năm mươi giống hoa hồng thương mại và hiện là nhà xuất khẩu lớn thứ hai trong khu vực.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0021', 'pdf_database', 'The recent increase in tourism has done less to improve the business of small retailers in this area than we ------- predicted.', 'original', 'originally', 'originated', 'originality', 'B', NULL, 'Sự gia tăng gần đây về du lịch đã làm ít hơn để cải thiện kinh doanh của các nhà bán lẻ nhỏ trong khu vực này so với dự đoán ban đầu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0022', 'pdf_database', 'Dr. Marsha Herbert''s illustrations were clear enough to make her presentation ------- understandable.', 'easily', 'easier', 'easy', 'ease', 'A', NULL, 'Hình minh họa của Tiến sĩ Marsha Herbert đủ rõ ràng để làm cho bài thuyết trình của cô dễ hiểu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0023', 'pdf_database', 'The guest speaker highlighted some ideas for -------introducing change in the workplace.', 'success', 'succeed', 'succeeding', 'successfully', 'D', NULL, 'Diễn giả khách mời đã nêu bật một số ý tưởng cho việc giới thiệu thành công sự thay đổi tại nơi làm việc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0024', 'pdf_database', 'Costs for building materials, such as cement, steel, and wood, rose -------last quarter, lowering the profits of most construction companies.', 'sharp', 'sharpness', 'sharply', 'sharpen', 'C', NULL, 'Chi phí cho vật liệu xây dựng, chẳng hạn như xi măng, thép và gỗ, tăng mạnh trong quý trước, làm giảm lợi nhuận của hầu hết các công ty xây dựng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0025', 'pdf_database', 'Following Ms. Aglo''s appointment to the board of directors, the firm''s investment strategy was -------reevaluated.', 'thoroughly', 'thorough', 'thoroughness', 'more thorough', 'A', NULL, 'Sau khi bà Aglo được bổ nhiệm vào hội đồng quản trị, chiến lược đầu tư của công ty đã được đánh giá lại một cách triệt để.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0026', 'pdf_database', 'Our contact information is printed on the back cover of the manual so that you may ------- refer to it.', 'ease', 'easy', 'easiest', 'easily', 'D', NULL, 'Thông tin liên lạc của chúng tôi được in ở mặt sau của hướng dẫn để bạn có thể dễ dàng tham khảo.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0027', 'pdf_database', 'The advertising budget is divided -------among the three divisions in the marketing department.', 'equal', 'equals', 'equality', 'equally', 'D', NULL, 'Ngân sách quảng cáo được chia đều cho ba bộ phận trong bộ phận tiếp thị.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0028', 'pdf_database', 'After-------failing to win customer support, Tykon''s upgraded software program has been withdrawn from the market.', 'repeat', 'repetition', 'repeated', 'repeatedly', 'D', NULL, 'Sau nhiều lần không giành được sự ủng hộ của khách hàng, chương trình phần mềm nâng cấp của Tykon đã bị rút khỏi thị trường.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0029', 'pdf_database', 'Since the item you ordered is -------out of stock, we are sending you a voucher for use toward a future purchase.', 'regretting', 'regrettably', 'regretted', 'regretful', 'B', NULL, 'Vì mặt hàng bạn đặt hàng đáng tiếc đã hết hàng, chúng tôi sẽ gửi cho bạn một phiếu mua hàng để sử dụng cho việc mua hàng trong tương lai.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0031', 'pdf_database', 'Library and information science majors should be reminded of the seminar beginning-------at 6:00 p.m. in room 212 B.', 'promptly', 'prompts', 'prompter', 'prompted', 'A', NULL, 'Những chuyên ngành thư viện và khoa học thông tin nên được nhắc nhở về buổi hội thảo bắt đầu ngay lúc 6:00 tối trong phòng 212 B.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0032', 'pdf_database', 'Local libraries -------offer reading programs for children and ESL for adults.', 'frequently', 'frequenting', 'frequent', 'frequented', 'A', NULL, 'Thư viện địa phương thường xuyên cung cấp các chương trình đọc cho trẻ em và ESL cho người lớn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0033', 'pdf_database', 'The board members meet only -------, usually only when there is a problem.', 'occasion', 'occasions', 'occasional', 'occasionally', 'D', NULL, 'Các thành viên hội đồng quản trị chỉ thỉnh thoảng gặp nhau, thường chỉ khi có vấn đề.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0034', 'pdf_database', 'New department heads must attend meetings------- in order to be exposed to new ideas from other team members.', 'frequent', 'frequenting', 'frequently', 'frequency', 'C', NULL, 'Trưởng bộ phận mới phải tham dự các cuộc họp thường xuyên để được tiếp xúc với những ý tưởng mới từ các thành viên khác trong nhóm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0035', 'pdf_database', 'Our aim is to focus on customers'' needs and satisfaction by ------- introducing exceptional goods.', 'consist', 'consistently', 'consistent', 'consisting', 'B', NULL, 'Mục tiêu của chúng tôi là tập trung vào nhu cầu và sự hài lòng của khách hàng bằng cách liên tục giới thiệu hàng hóa đặc biệt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0036', 'pdf_database', 'Finding qualified students for this job may be -------difficult.', 'extreme', 'extremes', 'extremely', 'extremity', 'C', NULL, 'Tìm kiếm những sinh viên đủ điều kiện cho công việc này có thể vô cùng khó khăn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0037', 'pdf_database', 'The new zoning laws should -------improve the traffic congestion problem developing in the suburbs.', 'great', 'greatness', 'greatly', 'greatest', 'C', NULL, 'Các luật quy hoạch mới sẽ cải thiện đáng kể vấn đề tắc nghẽn giao thông đang phát triển ở vùng ngoại ô.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0038', 'pdf_database', 'The price of organic foods is expected to rise -------over the next several years because of an increase in demand.', 'dramatize', 'dramatically', 'dramatist', 'dramatic', 'B', NULL, 'Giá thực phẩm hữu cơ dự kiến sẽ tăng mạnh trong vài năm tới vì nhu cầu tăng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0039', 'pdf_database', 'Mr. Wilt Flaherty from the Stemcor Company -------announced some good news to shareholders at the last meeting.', 'final', 'finalist', 'finalize', 'finally', 'D', NULL, 'Ông Wilt Flaherty từ Công ty Stemcor cuối cùng đã thông báo một số tin tốt cho các cổ đông tại cuộc họp cuối cùng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0040', 'pdf_database', 'Mr. Ben Shipley will be promoted next month for -------managing production at our facility in Kansas City.', 'effective', 'effectively', 'more effective', 'most effective', 'B', NULL, 'Ông Ben Shipley sẽ được thăng chức vào tháng tới cho việc quản lý hiệu quả việc sản xuất tại cơ sở của chúng tôi ở Thành phố Kansas.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0041', 'pdf_database', 'Van Dusen Enterprises is a leader in exploring agricultural innovations that are environmentally friendly and -------beneficial.', 'economics', 'more economical', 'economic', 'economically', 'D', NULL, 'Van Dusen Enterprises là một nhà lãnh đạo trong việc khám phá các đổi mới nông nghiệp thân thiện với môi trường và có lợi về mặt kinh tế.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0042', 'pdf_database', 'After-------interviewing more than fifty candidates for the position of manager of the Biotechnology Department, the committee chose Dr. Alan Liu.', 'carefully', 'to care', 'most careful', 'careful', 'A', NULL, 'Sau khi phỏng vấn cẩn thận hơn năm mươi ứng viên cho vị trí quản lý của Cục Công nghệ sinh học, ủy ban đã chọn Tiến sĩ Alan Liu.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0043', 'pdf_database', 'A few vehicles were ------- damaged by the recent hailstorm and will have to be replaced immediately.', 'severely', 'severe', 'severeness', 'severity', 'A', NULL, 'Một vài chiếc xe đã bị hư hại nặng nề bởi trận mưa đá gần đây và sẽ phải được thay thế ngay lập tức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0044', 'pdf_database', 'Andrew Hartwell is ------- regarded by his employees because of his dedication and experience.', 'highly', 'high', 'highest', 'higher', 'A', NULL, 'Andrew Hartwell được các nhân viên của mình đánh giá cao vì sự cống hiến và kinh nghiệm của mình.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0045', 'pdf_database', 'The chemistry lab managers are concerned that new employees have not been trained ------- in the latest emergency procedures.', 'adequate', 'adequacy', 'adequately', 'adequateness', 'C', NULL, 'Các nhà quản lý phòng thí nghiệm hóa học lo ngại rằng nhân viên mới chưa được đào tạo đầy đủ về các quy trình khẩn cấp mới nhất.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0046', 'pdf_database', 'The journal is published every four months, and ------- available to other member societies under agreement of payment and publication.', 'official', 'officials', 'officially', 'officialize', 'C', NULL, 'Tạp chí được xuất bản bốn tháng một lần, và chính thức có sẵn cho các tổ chức thành viên khác theo thỏa thuận thanh toán và xuất bản.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0047', 'pdf_database', 'The overall satisfaction of participants with the workshop is often based on ------- unimportant details such as the ability to park close to the training facility.', 'seems', 'seeming', 'seemingly', 'seemed', 'C', NULL, 'Sự hài lòng chung của những người tham gia hội thảo thường dựa trên các chi tiết dường như không quan trọng như khả năng đỗ xe gần cơ sở đào tạo.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0048', 'pdf_database', 'Shareholders voted that Deborah LaSalle is -------suited for the position of chief operating officer given her experience.', 'ideal', 'ideally', 'idealized', 'ideality', 'B', NULL, 'Các cổ đông đã bình chọn rằng Deborah LaSalle phù hợp một cách lý tưởng cho vị trí giám đốc điều hành vì kinh nghiệm của cô.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0049', 'pdf_database', 'The CEO -------appointed James Farley as vice president of Arctic Mining Ventures Co.', 'formalize', 'formally', 'formal', 'formality', 'B', NULL, 'Giám đốc điều hành chính thức bổ nhiệm James Farley làm phó chủ tịch của Arctic Mining Ventures Co.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0050', 'pdf_database', 'Amateur theatrical performances by locals and some appearances by renowned poets were ------- reviewed by journalists in the Eberlein County Daily.', 'positive', 'positively', 'positivity', 'positiveness', 'B', NULL, 'Các buổi biểu diễn sân khấu nghiệp dư của người dân địa phương và một số lần xuất hiện của các nhà thơ nổi tiếng đã được các nhà báo đánh giá tích cực trên tờ Eberlein County Daily.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0051', 'pdf_database', 'Prattchet Co. has-------turned to making most of its products from recycled materials.', 'increasingly', 'increasing', 'increased', 'increase', 'A', NULL, 'Công ty Pratchett ngày càng chuyển sang sản xuất hầu hết các sản phẩm của mình từ vật liệu tái chế.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0052', 'pdf_database', 'New government regulations concerning the chemicals in cleaning solutions mean that the solvents must be as -------safe as possible.', 'environments', 'environmentalists', 'environmentally', 'environmental', 'C', NULL, 'Các quy định mới của chính phủ liên quan đến các hóa chất trong dung dịch tẩy rửa có nghĩa là dung môi phải an toàn với môi trường nhất có thể.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0053', 'pdf_database', 'Once Mr. Mirren -------completes his studies and necessary training, he may come and work for our corporation.', 'success', 'successful', 'successfully', 'successes', 'C', NULL, 'Một khi ông Mirren hoàn thành một cách thành công việc học và đào tạo cần thiết, ông có thể đến và làm việc cho tập đoàn của chúng tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0054', 'pdf_database', 'The two competing software programs were determined to be ------- effective in making filing taxes from home an easy task.', 'equal', 'equally', 'equaled', 'equality', 'B', NULL, 'Hai chương trình phần mềm cạnh tranh được xác định là có hiệu quả như nhau trong việc làm cho việc nộp thuế từ nhà trở thành một nhiệm vụ dễ dàng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0055', 'pdf_database', 'When handling large funds, bank employees are required to check the statements ------to make sure that everything is correct.', 'careful', 'carefully', 'more careful', 'carefulness', 'B', NULL, 'Khi xử lý các khoản tiền lớn, nhân viên ngân hàng được yêu cầu kiểm tra các báo cáo cẩn thận để đảm bảo rằng mọi thứ đều chính xác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0056', 'pdf_database', 'The Phalanx Bus Co. reminds passengers to ------- refrain from propping their feet against the seat in front of them.', 'kind', 'kindly', 'kindlier', 'kinder', 'B', NULL, 'Công ty xe buýt Phalanx nhắc nhở hành khách vui lòng kiềm chế không chống chân lên ghế trước mặt họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0057', 'pdf_database', 'Bananas imported from the Philippines are dominating supermarket shelves -------due to their attractive appearance.', 'reported', 'reportedly', 'reporting', 'reports', 'B', NULL, 'Chuối nhập khẩu từ Philippines đang thống trị các kệ hàng siêu thị do vẻ ngoài hấp dẫn của chúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0058', 'pdf_database', 'We are pleased to announce that the -------anticipated tablet computer brochure has now been launched on our website.', 'most eager', 'eagerness', 'eagerly', 'eager', 'C', NULL, 'Chúng tôi vui mừng thông báo rằng tài liệu quảng cáo máy tính bảng được mong chờ một cách háo hức hiện đã được tung ra trên trang web của chúng tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0059', 'pdf_database', 'He -------delivers keynote speeches and holds workshops on customer satisfaction strategy and the building of profitable customer relationships.', 'regularize', 'regularity', 'regularities', 'regularly', 'D', NULL, 'Ông thường xuyên đưa ra các bài phát biểu quan trọng và tổ chức các hội thảo về chiến lược hài lòng của khách hàng và xây dựng các mối quan hệ khách hàng có lợi nhuận.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0060', 'pdf_database', 'Needs assessment can help you identify areas for improvement and ultimately help you realize your goals more-------.', 'efficient', 'efficiency', 'efficiencies', 'efficiently', 'D', NULL, 'Việc đánh giá nhu cầu có thể giúp bạn xác định các lĩnh vực cần cải thiện và cuối cùng giúp bạn nhận ra mục tiêu của mình một cách hiệu quả hơn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0061', 'pdf_database', 'Mr. Henny -------presented the argument that the pricing policy of the retailer would be the financial ruin of the company.', 'convinces', 'convince', 'convincingly', 'convincing', 'C', NULL, 'Ông Henny trình bày một cách thuyết phục rằng chính sách giá của nhà bán lẻ sẽ là sự hủy hoại tài chính của công ty.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0062', 'pdf_database', 'Sign up to receive our tree newsletter and you will ------- receive update notifications and other news via e-mail.', 'automatically', 'automaticity', 'automated', 'automatic', 'A', NULL, 'Đăng ký để nhận bản tin thực vật của chúng tôi và bạn sẽ tự động nhận được thông báo câp nhật và tin tức khác qua e-mail.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0063', 'pdf_database', 'When compared with the traditional method of cleaning by wet mopping, the new method was ------- more effective in removal of microbial contamination.', 'signify', 'significant', 'significantly', 'significance', 'C', NULL, 'Khi được so sánh với phương pháp làm sạch truyền thống bằng cách lau ướt, phương pháp mới có hiệu quả rõ rệt hơn trong việc loại bỏ ô nhiễm vi khuẩn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0064', 'pdf_database', 'QIB will work-------to maintain sustainable growth and expansion plans.', 'persisted', 'persistent', 'persistently', 'persistence', 'C', NULL, 'QIB sẽ làm việc bền bỉ để duy trì các kế hoạch mở rộng và tăng trưởng bền vững.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0065', 'pdf_database', 'Wholesale buyers purchase merchandise-------from manufacturers and resell it to retail firms, commercial establishments, and other institutions.', 'directing', 'directs', 'directly', 'directed', 'C', NULL, 'Người mua bán buôn mua hàng hóa trực tiếp từ các nhà sản xuất và bán lại cho các công ty bán lẻ, cơ sở thương mại và các tổ chức khác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0066', 'pdf_database', 'If you participate in online forums or attend events-------, you will get to know other members a lot better.', 'regularly', 'regular', 'regulars', 'regularity', 'A', NULL, 'Nếu bạn tham gia các diễn đàn trực tuyến hoặc tham dự các sự kiện thường xuyên, bạn sẽ hiểu rõ hơn về các thành viên khác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0067', 'pdf_database', 'Since distance learners cannot meet with their supervisors -------due to logistical problems, so it is necessary for the educational institution to facilitate two-way communication channels.', 'frequents', 'frequent', 'frequently', 'frequency', 'C', NULL, 'Vì người học từ xa không thể gặp người giám sát thường xuyên do các vấn đề hậu cần, nên cơ sở giáo dục cần phải tạo điều kiện cho các kênh liên lạc hai chiều.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0068', 'pdf_database', 'Drexel''s Paints imports most of its watercolor-related products -------from England.', 'directs', 'directed', 'direction', 'directly', 'D', NULL, 'Drexel''s Paints nhập khẩu hầu hết các sản phẩm liên quan đến màu nước trực tiếp từ Anh.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-08-b0069', 'pdf_database', 'The sales force has expanded so rapidly this year that it will ------- be split into different teams next year.', 'inevitable', 'inevitability', 'inevitably', 'inevitable that', 'C', NULL, 'Lực lượng bán hàng đã mở rộng nhanh chóng trong năm nay đến nỗi mà chắc chắn sẽ bị chia thành các đội khác nhau vào năm tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
