INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0004', 'pdf_database', 'Answering customer questions is sometimes difficult to do on -------, so we have created a list of frequently asked questions.', 'yours', 'yourself', 'your own', 'you', 'C', NULL, 'Trả lời câu hỏi của khách hàng đôi khi rất khó để tự làm, vì vậy chúng tôi đã tạo một danh sách các câu hỏi thường gặp.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0005', 'pdf_database', 'Mr. Kato left the hotel''s telephone number with the airport staff so they could notify ------- when the luggage is found.', 'him', 'himself', 'he', 'his', 'A', NULL, 'Ông Kato để lại số điện thoại của khách sạn với nhân viên sân bay để họ có thể thông báo cho ông khi hành lý được tìm thấy.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0006', 'pdf_database', 'The mechanics became more efficient as ------- began using the new technology.', 'themselves', 'them', 'their', 'they', 'D', NULL, 'Các thợ máy trở nên hiệu quả hơn khi họ bắt đầu sử dụng công nghệ mới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0007', 'pdf_database', 'After her retirement, Lillian will certainly be missed by the numerous colleagues who have benefited from -------steady judgment in the field of finance.', 'she', 'her', 'hers', 'herself', 'B', NULL, 'Sau khi nghỉ hưu, nhiều đồng nghiệp những người mà đã được hưởng lợi từ sự phán đoán ổn định của cô trong lĩnh vực tài chính chắc chắn sẽ nhớ cô Lillian.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0008', 'pdf_database', 'Staff who need to replace -------equipment must submit an upgrade request form.', 'them', 'their', 'themselves', 'theirs', 'B', NULL, 'Nhân viên người cần thay thế thiết bị của họ phải nộp mẫu yêu cầu nâng cấp.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0009', 'pdf_database', 'The user''s manual explains all the controls and functions of ------- Pictor Series V television.', 'you', 'your', 'yours', 'yourself', 'B', NULL, 'Hướng dẫn sử dụng giải thích tất cả các điều khiển và chức năng của tivi V Series Series của bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0010', 'pdf_database', 'If the discontinued printers are not sold by Friday, Ainley Electronics will offer-------at 50 percent off.', 'they', 'their', 'them', 'themselves', 'C', NULL, 'Nếu các máy in ngừng sản xuất không được bán vào thứ Sáu, Ainley Electronics sẽ giảm giá 50% cho chúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0011', 'pdf_database', 'While he is away from the office, we can reach Mr. Cho by calling -------home phone number.', 'himself', 'him', 'he', 'his', 'D', NULL, 'Khi anh ấy đi khỏi văn phòng, chúng tôi có thể liên lạc với anh Cho bằng cách gọi số điện thoại nhà của anh ấy.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0012', 'pdf_database', 'The company is going to carry out the proposal based on the information provided in your letter of intent, so please submit ------- application under this note.', 'you', 'your', 'yourself', 'yours', 'B', NULL, 'Công ty sẽ thực hiện đề xuất dựa trên thông tin được cung cấp trong thư dự định của bạn, vì vậy vui lòng gửi đơn đăng ký của bạn theo ghi chú này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0013', 'pdf_database', 'As soon as the shipment of computer equipment comes in, -------will ship it to you promptly.', 'we', 'us', 'our', 'ourselves', 'A', NULL, 'Ngay sau khi lô hàng thiết bị máy tính đến, chúng tôi sẽ gửi nó cho bạn kịp thời.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0014', 'pdf_database', 'The head of the marketing department attributed success in the overseas market to ------- motivated and hard-working employees.', 'them', 'they', 'itself', 'its', 'D', NULL, 'Người đứng đầu bộ phận tiếp thị cho rằng việc thành công ở thị trường nước ngoài là nhờ các nhân viên năng động và chăm chỉ của nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0015', 'pdf_database', '------- habitually answers incoming phone calls and signs for packages while in the office.', 'She', 'Her', 'Hers', 'Herself', 'A', NULL, 'Cô thường xuyên trả lời các cuộc gọi điện thoại và ký cho các gói hàng khi ở trong văn phòng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0016', 'pdf_database', 'Drivers are required to carry ------- liability insurance policy at all times in their cars· in case of an accident.', 'their', 'theirs', 'they', 'themselves', 'A', NULL, 'Lái xe được yêu cầu thực hiện chính sách bảo hiểm trách nhiệm pháp lý của họ mọi lúc trong xe của họ trong trường hợp tai nạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0017', 'pdf_database', 'Drivers are asked to park their cars by -------rather than using a valet parking system.', 'they', 'their', 'them', 'themselves', 'D', NULL, 'Các tài xế được yêu cầu tự đỗ xe hơn là sử dụng hệ thống đỗ xe.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0018', 'pdf_database', 'If you have difficulty preparing for a presentation on-------, ask Mr. Jacobs for help.', 'your own', 'yourself', 'your', 'yours', 'A', NULL, 'Nếu bạn gặp khó khăn trong việc tự mình chuẩn bị cho một bài thuyết trình, hãy nhờ ông Jacobs giúp đỡ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0019', 'pdf_database', 'APT Electronics has proved ------- capable of achieving impressive revenues just in the first quarter.', 'it', 'themselves', 'those', 'itself', 'D', NULL, 'APT Electronics đã chứng tỏ mình có khả năng đạt được doanh thu ấn tượng chỉ trong quý đầu tiên.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0020', 'pdf_database', 'Passengers on the aircraft are asked to secure ------- belongings during takeoff and landing.', 'they', 'their', 'them', 'themselves', 'B', NULL, 'Hành khách trên máy bay được yêu cầu bảo đảm đồ đạc trong quá trình cất cánh và hạ cánh.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0021', 'pdf_database', 'Although the staff has grown, Mr. Lee continues to conduct all client meetings -------', 'he', 'him', 'his', 'himself', 'D', NULL, 'Mặc dù đội ngũ nhân viên đã phát triển, ông Lee vẫn tiếp tục tự mình thực hiện tất cả các cuộc họp của khách hàng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0022', 'pdf_database', 'Dr. Tang has been chosen to accept -------award on behalf of the development team.', 'our', 'ours', 'us', 'we', 'A', NULL, 'Tiến sĩ Tang đã được chọn để nhận giải thưởng của chúng tôi thay mặt cho nhóm phát triển.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0023', 'pdf_database', 'Mr. Kang started-------printing business 25 years ago in Pusan, South Korea.', 'he', 'him', 'his', 'himself', 'C', NULL, 'Ông Kang bắt đầu kinh doanh in ấn 25 năm trước tại Pusan, Hàn Quốc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0024', 'pdf_database', 'Ms. Jackson said she would prefer to work on the report by -------before submitting a draft for the committee''s approval.', 'her', 'hers', 'herself', 'she', 'C', NULL, 'Cô Jackson cho biết cô muốn tự mình làm báo cáo trước khi đệ trình dự thảo phê duyệt của ủy ban.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0025', 'pdf_database', 'Although multiple studies were conducted by market research groups, it is still uncertain whether customers are ready to purchase ------- groceries on the Internet.', 'ours', 'theirs', 'their', 'ourselves', 'C', NULL, 'Mặc dù nhiều nghiên cứu được thực hiện bởi các nhóm nghiên cứu thị trường, nhưng vẫn không chắc chắn liệu khách hàng có sẵn sàng mua hàng tạp hóa của họ trên Internet hay không.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0026', 'pdf_database', 'All shipments arrive at the receiving dock, where a warehouse worker checks -------tracking labels.', 'theirs', 'they', 'them', 'their', 'D', NULL, 'Tất cả các lô hàng đến bến nhận, nơi mà một nhân viên kho kiểm tra nhãn theo dõi của chúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0027', 'pdf_database', 'We will have to inform Mr. Yamamoto that ------- application cannot be accepted at this time.', 'he', 'himself', 'his', 'him', 'C', NULL, 'Chúng tôi sẽ phải thông báo cho ông Yamamoto rằng đơn đăng ký của ông không thể được chấp nhận tại thời điểm này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0028', 'pdf_database', 'In order for Mr. Song''s group to complete the data collection project on time, -------will need even more administrative support.', 'us', 'we', 'our', 'ourselves', 'B', NULL, 'Để nhóm của ông Song hoàn thành dự án thu thập dữ liệu đúng hạn, chúng tôi sẽ cần nhiều hỗ trợ hành chính hơn nữa.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0029', 'pdf_database', 'With ------- new building and expanded hours, First Bank of Stubenville is once again ahead of the competition.', 'them', 'they', 'its', 'itself', 'C', NULL, 'Với tòa nhà mới và giờ mở rộng của nó , First Bank of Steubenville một lần nữa đi trước đối thủ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0030', 'pdf_database', 'Mr. Adams will not be able to complete the report by himself and would appreciate it if someone would volunteer to help -------.', 'he', 'him', 'himself', 'his', 'B', NULL, 'Ông Adams sẽ không thể tự hoàn thành báo cáo và sẽ đánh giá cao nếu có ai đó tình nguyện giúp ông.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
