INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0032', 'pdf_database', 'Those who have questions concerning fringe benefits are advised to consult ------- employee handbook.', 'their', 'they', 'themselves', 'theirs', 'A', NULL, 'Những người có câu hỏi liên quan đến lợi ích phụ nên tham khảo sổ tay nhân viên của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0033', 'pdf_database', 'The two divisions have unveiled ------- plan to set aside millions of dollars to invest in a very lucrative field.', 'they', 'them', 'their', 'those', 'C', NULL, 'Hai bộ phận đã tiết lộ kế hoạch của họ để dành hàng triệu đô la để đầu tư vào một lĩnh vực rất sinh lợi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0034', 'pdf_database', 'Mr. Kurt Spienza appears to be the only person in our team who can finish the survey by----.', 'he', 'him', 'his', 'himself', 'D', NULL, 'Ông Kurt Spienza dường như là người duy nhất trong nhóm chúng tôi có thể tự mình hoàn thành khảo sát.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0035', 'pdf_database', 'It seems that laborers in underdeveloped countries would rather have their children help -------at work than enroll them in school.', 'they', 'them', 'themselves', 'their', 'B', NULL, 'Dường như những người lao động ở các nước kém phát triển thà để con cái họ giúp họ làm việc hơn là đăng ký cho chúng đi học.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0036', 'pdf_database', 'Thank you for offering me a position with the company I wish to work for, and I really appreciate the efforts you''ve made on ------- behalf.', 'I', 'my', 'me', 'mine', 'B', NULL, 'Cảm ơn bạn đã cung cấp cho tôi một vị trí với công ty tôi muốn làm việc và tôi thực sự đánh giá cao những nỗ lực mà bạn đã làm thay mặt tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0037', 'pdf_database', 'Considering the failure of -------system to offer adequate support, we might have to provide refunds to our customers.', 'us', 'ours', 'ourselves', 'our', 'D', NULL, 'Xem xét sự thất bại của hệ thống của chúng tôi để cung cấp hỗ trợ đầy đủ, chúng tôi có thể phải hoàn lại tiền cho khách hàng của chúng tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0038', 'pdf_database', 'Our skilled and experienced service representatives will be able to resolve any problems you might encounter by -------.', 'himself', 'herself', 'itself', 'themselves', 'D', NULL, 'Đại diện dịch vụ có kĩ năng và giàu kinh nghiệm của chúng tôi sẽ có thể tự giải quyết mọi vấn đề bạn có thể gặp phải.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0039', 'pdf_database', 'Ms. Cordova was struggling to successfully complete the task assigned to her by ------', 'herself', 'he', 'hers', 'she', 'A', NULL, 'Cô Cordova đang cố gắng hoàn thành thành công nhiệm vụ được giao.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0040', 'pdf_database', 'Most of the employees are entitled to a maximum of one hour for a lunch break, depending on -------assigned work schedule.', 'ours', 'their', 'theirs', 'ourselves', 'B', NULL, 'Hầu hết các nhân viên được hưởng tối đa một giờ để nghỉ trưa, tùy thuộc vào lịch làm việc được giao của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0041', 'pdf_database', 'The report shows that builders reserve the right to control the volume of the construction project on -------own.', 'their', 'theirs', 'they', 'them', 'A', NULL, 'Báo cáo cho thấy các nhà xây dựng có quyền tự mình kiểm soát khối lượng của dự án xây dựng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0042', 'pdf_database', 'While Ms. Jamison''s study focused on consumer spending generally, -------- deals more specifically with purchasing trends among 18 to 24 year olds.', 'I', 'my', 'me', 'mine', 'D', NULL, 'Trong khi nghiên cứu của cô Jamison tập trung vào chi tiêu của người tiêu dùng nói chung, nghiên cứu của tôi cụ thể hơn về xu hướng mua hàng trong độ tuổi từ 18 đến 24.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0043', 'pdf_database', 'Author Ken Yabuki wrote a magazine article based on -------recent visit to Iceland.', 'he', 'his', 'him', 'himself', 'B', NULL, 'Tác giả Ken Yabuki đã viết một bài báo trên tạp chí dựa trên chuyến thăm gần đây của ông đến Iceland.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0044', 'pdf_database', 'Effective publicity helps a company keep a high profile by reminding the public of ------- most successful or innovative products.', 'they', 'them', 'its', 'it', 'C', NULL, 'Sự công khai hiệu quả giúp một công ty giữ một hồ sơ cao bằng cách nhắc nhở công chúng về các sản phẩm thành công hoặc sáng tạo nhất của nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0045', 'pdf_database', 'Jorge was hired as an assistant manager five months ago, and -------is now in line for a promotion.', 'himself', 'him', 'his', 'he', 'D', NULL, 'Jorge được thuê làm trợ lý giám đốc năm tháng trước và hiện anh đang nằm trong danh sách để được thăng chức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0046', 'pdf_database', 'We hope to send -------tax documents to you by the end of the week.', 'you', 'your', 'yours', 'yourself', 'B', NULL, 'Chúng tôi hy vọng sẽ gửi tài liệu thuế của bạn cho bạn vào cuối tuần.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0047', 'pdf_database', 'Because of -------extremely focused customer bases, small business owners can often respond quickly to new economic trends.', 'they', 'their', 'theirs', 'them', 'B', NULL, 'Do cơ sở khách hàng được tập trung cực kỳ của họ, các chủ doanh nghiệp nhỏ thường có thể đáp ứng nhanh chóng với các xu hướng kinh tế mới', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0048', 'pdf_database', 'If you have any questions about Maxiel Corporation''s services,·please visit-------Web site.', 'we', 'us', 'our', 'ourselves', 'C', NULL, 'Nếu bạn có bất kỳ câu hỏi nào về các dịch vụ của Maxiel Corporation, vui lòng truy cập trang web của chúng tôi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0049', 'pdf_database', 'Although measures have been introduced to discourage the use of mobile telephones inside the opera house,-------effectiveness remains limited.', 'they', 'their', 'them', 'theirs', 'B', NULL, 'Mặc dù các biện pháp đã được đưa ra để ngăn chặn việc sử dụng điện thoại di động trong nhà hát opera, hiệu quả của chúng vẫn còn hạn chế.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-11-b0050', 'pdf_database', 'Although Oliver Rodriguez'' books have shaped the way that businesses handle staff relations, he does not consider -------an expert on the subject.', 'he', 'him', 'his', 'himself', 'D', NULL, 'Mặc dù các cuốn sách của Oliver Rodriguez đã định hình cách các doanh nghiệp xử lý các mối quan hệ nhân viên, nhưng anh ta không coi mình là một chuyên gia về vấn đề này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0024', 'pdf_database', 'As heath care become ------- than it was a decade ago, companies are forced to spend more on benefits.', 'as expensive', 'more expensive', 'so expensive', 'most expensively', 'B', NULL, 'Bởi vì việc chăm sóc sức khỏe trở nên đắt đỏ hơn so với một thập kỷ trước, các công ty buộc phải chi nhiều hơn cho tiền trợ cấp.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0025', 'pdf_database', 'Many online retailers state that it is ------- than they expected to set price that attract more customers while boosting their profit.', 'difficult', 'diffculty', 'more diffcult', 'much diffcult', 'C', NULL, 'Nhiều nhà bán lẻ trực tuyến nói rằng để đặt giá thu hút nhiều khách hàng hơn trong khi tăng lợi nhuận của họ thì khó khăn hơn họ mong đợi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0026', 'pdf_database', 'Questions concerning whether international trade is ------- more beneficial to lower income economies have been raised for years.', 'much', 'such', 'very', 'too', 'A', NULL, 'Các câu hỏi liên quan đến liệu rằng thương mại quốc tế có lợi hơn nhiều cho các nền kinh tế có thu nhập thấp hơn đã được đưa ra trong nhiều năm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0027', 'pdf_database', 'They seemed eager to do all they could to make my stay as--------- as possible.', 'comfort', 'comfortable', 'comfortably', 'comforted', 'B', NULL, 'Họ có vẻ háo hức làm tất cả những gì họ có thể để làm cho tôi ở lại thoải mái nhất có thể.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0028', 'pdf_database', 'If the company had been under better circumstances, it could have obtained an ------- more favorable outcome.', 'all', 'even', 'any', 'almost', 'B', NULL, 'Nếu công ty đã ở trong hoàn cảnh tốt hơn, nó có thể đã đạt được một kết quả thậm chí còn thuận lợi hơn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0029', 'pdf_database', 'Of the 6 candidates, Ms. Sally Marson seemed the ------- for the position.', 'qualification', 'qualified', 'more qualified', 'most qualified', 'D', NULL, 'Trong số 6 ứng cử viên, bà Sally Marson có vẻ đủ điều kiện nhất cho vị trí này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0030', 'pdf_database', 'The use of the ------- possible lighting in the laboratory has been beneficial to the research conducted by the botanists employed.', 'bright', 'brightest', 'brightens', 'brightness', 'B', NULL, 'Việc sử dụng ánh sáng mạnh nhất có thể trong phòng thí nghiệm có lợi cho nghiên cứu được thực hiện bởi các nhà thực vật học người mà được thuê.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0031', 'pdf_database', 'I’ve read a couple of different articles on Franklin Roosevelt, who was a much ------- president than Barack Obama has been.', 'boldness', 'bolder', 'boldest', 'boldly', 'B', NULL, 'Tôi đã đọc một vài bài báo khác nhau về Franklin Roosevelt, một tổng thống táo bạo hơn nhiều so với Barack Obama.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0032', 'pdf_database', 'Improving our customer outreach program is ------- important than recognizing our office system right now.', 'better', 'more', 'well', 'greater', 'B', NULL, 'Cải thiện chương trình tiếp cận khách hàng của chúng tôi quan trọng hơn là nhận ra hệ thống văn phòng của chúng tôi ngay bây giờ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0033', 'pdf_database', 'At this firm, young, motivated candidates who show enthusiasm have ------- value as experienced professionals.', 'a lot', 'also', 'as much', 'so many', 'C', NULL, 'Tại công ty này, các ứng viên trẻ, có động lực thể hiện sự nhiệt tình có giá trị như các chuyên gia giàu kinh nghiệm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
