INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0035', 'pdf_database', 'Due to the alleged scandal, the corporation was receiving more attention ------- that which was good for business.', 'so', 'such', 'too', 'than', 'D', NULL, 'Do vụ bê bối bị cáo buộc, tập đoàn đã nhận được nhiều sự chú ý hơn là điều tốt cho kinh doanh.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-12-b0036', 'pdf_database', 'In order to help factory workers to work much ------, the new Samson machines will be installed next week.', 'more efficiently', 'efficiently', 'efficient', 'most efficiently', 'A', NULL, 'Để giúp công nhân nhà máy làm việc hiệu quả hơn nhiều, các máy Samson mới sẽ được lắp đặt vào tuần tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
