INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0016', 'pdf_database', '__________than what I know yesterday, I would have saved myself a lot of time and trouble over the years.', 'had I known', 'did I know', 'If I know', 'If I would know', 'A', NULL, 'Nếu tôi biết nhiều hơn cái tôi biết ngày hôm qua, tôi sẽ tiết kiệm cho mình rất nhiều thời gian và rắc rối trong những năm qua.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0017', 'pdf_database', 'Do you think there would be less conflict in the world if all people __________the same language?', 'spoke', 'speak', 'had spoken', 'will spea', 'A', NULL, 'Bạn có nghĩ rằng sẽ có ít xung đột hơn trên thế giới nếu tất cả mọi người nói cùng một ngôn ngữ?', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0018', 'pdf_database', 'If you can give me one good reason for your acting like this, __________this incident again.', 'I will never mention', 'I never mention', 'will I never mention', 'I don''t mention', 'A', NULL, 'Nếu bạn có thể cho tôi một lý do tốt cho cách hành xử của bạn như thế này, tôi sẽ không bao giờ đề cập đến sự cố này nữa.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0019', 'pdf_database', 'If I had known you were asleep, I __________so much noise when I came in.', 'didn''t make', 'wouldn''t have made', 'won''t make', 'don''t make', 'B', NULL, 'Nếu tôi biết bạn đã ngủ, tôi sẽ không gây ra nhiều tiếng ồn khi tôi bước vào.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0020', 'pdf_database', 'Bổ sung: If I had known you were asleep, I __________so much noise when I come in.', 'didn''t make', 'wouldn''t have made', 'won''t make', 'wouldn’t make', 'D', NULL, 'Nếu tôi biết bạn đã ngủ, tôi sẽ không gây ra nhiều tiếng ồn khi tôi bước vào.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0021', 'pdf_database', 'Unless you __________all of my questions, I can''t do anything to help you.', 'answered', 'answer', 'would answer', 'are answering', 'B', NULL, 'Trừ khi bạn trả lời tất cả các câu hỏi của tôi, tôi không thể làm gì để giúp đỡ bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0022', 'pdf_database', 'Had you told me that this was going to happen, I __________it.', 'would have never believed', 'don''t believe', 'hadn''t believed', 'can''t believe', 'A', NULL, 'Nếu bạn nói với tôi rằng điều này sẽ xảy ra, tôi sẽ không bao giờ tin nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0023', 'pdf_database', 'If you __________, I would have brought my friends over to your house yesterday to watch T.V, but I didn''t want to bother you.', 'had studied', 'studied', 'hadn''t studied', 'didn''t study', 'C', NULL, 'Nếu bạn không học, tôi đã đưa bạn bè của tôi đến nhà bạn ngày hôm qua để xem T.V, nhưng tôi không muốn làm phiền bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
