INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0026', 'pdf_database', 'If I didn''t work for an accounting firm, I __________in a bank now.', 'work', 'will work', 'have worked', 'would work', 'D', NULL, 'Nếu tôi không làm việc cho một công ty kế toán, tôi sẽ làm việc trong một ngân hàng bây giờ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
