INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0028', 'pdf_database', 'If she __________ him, she would be very happy.', 'would meet', 'will meet', 'met', 'should meet', 'C', NULL, 'Nếu cô ấy gặp anh ấy, cô sẽ rất hạnh phúc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0029', 'pdf_database', 'If he __________ a thorough knowledge of English, he could have applied for this post.', 'had had', 'had', 'has', 'has had', 'A', NULL, 'Nếu anh ta có kiến thức kỹ lưỡng về tiếng Anh, anh ta có thể đã nộp đơn cho vị trí này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0030', 'pdf_database', 'If I had enough money, I__________ abroad to improve my English.', 'will go', 'would go', 'went', 'should have go to', 'B', NULL, 'Nếu tôi có đủ tiền, tôi sẽ ra nước ngoài để cải thiện tiếng Anh của mình.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0032', 'pdf_database', 'If orders ------- at the current pace all summer, Turramurra Luggage Company will meet its sales goal one month early.', 'receive', 'are received', 'will receive', 'will be receiving', 'B', NULL, 'Nếu đơn đặt hàng được nhận với tốc độ hiện tại suốt mùa hè, Công ty Hành lý Turramurra sẽ đáp ứng mục tiêu bán hàng sớm một tháng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0033', 'pdf_database', 'If measures had not been taken to reduce company expenses, the added costs would ------- by the customer.', 'assusme', 'have been assumed', 'had been assumed', 'be assuming', 'B', NULL, 'Nếu các biện pháp không được thực hiện để giảm chi phí của công ty, thì chi phí gia tăng sẽ được thừa nhận bởi khách hàng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0034', 'pdf_database', 'If customers were unhappy with the quality of a product, the store ------- it or provide a refund.', 'would exchange', 'exchange', 'have exchanged', 'will exchange', 'A', NULL, 'Nếu khách hàng không hài lòng với chất lượng sản phẩm, cửa hàng sẽ đổi hoặc hoàn lại tiền.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0035', 'pdf_database', 'The reductions in the budget will have serious implications if the projects ------- in the next quarter.', 'will be executed', 'executes', 'are executed', 'will execute', 'C', NULL, 'Việc cắt giảm ngân sách sẽ có tác động nghiêm trọng nếu các dự án được thực hiện trong quý tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0036', 'pdf_database', 'If personal income taxes had been lowered, the national economy ------- much more quickly.', 'recovered', 'has recovered', 'would have recovered', 'has been recovered', 'C', NULL, 'Nếu thuế thu nhập cá nhân đã được hạ xuống, nền kinh tế quốc gia sẽ phục hồi nhanh hơn nhiều.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0037', 'pdf_database', 'If laws do not change and continue to favor creditors, many small-scale companies ------- bankrupt.', 'have gone', 'will go', 'went', 'goes', 'B', NULL, 'Nếu luật pháp không thay đổi và tiếp tục ủng hộ các chủ nợ, nhiều công ty quy mô nhỏ sẽ phá sản.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0038', 'pdf_database', 'The supervisor commented that the manual could ------- bettter had the company hired an editor to go over the material before it was printed.', 'organize', 'be organized', 'have organized', 'have been organized', 'D', NULL, 'Người giám sát nhận xét rằng hướng dẫn có thể được tổ chức tốt hơn nếu công ty thuê một biên tập viên để xem qua tài liệu trước khi nó được in.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0039', 'pdf_database', 'The recurring problem of unheated rooms would ------- if the owner had responded to the tenants’initial complaints.', 'have been elimination', 'had been eliminated', 'have been eliminated', 'have been eliminating', 'C', NULL, 'Vấn đề xảy ra liên tiếp của các phòng không được sưởi ấm sẽ được loại bỏ nếu chủ sở hữu đã trả lời các khiếu nại ban đầu của người thuê.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0040', 'pdf_database', 'If the error had not been reported, the customer ------- his order until after the Christmas season had ended.', 'would not have received', 'would not receive', 'did not receive', 'would not be receive', 'A', NULL, 'Nếu lỗi không được báo cáo, khách hàng sẽ không nhận được đơn đặt hàng của mình cho đến khi mùa Giáng sinh kết thúc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0041', 'pdf_database', 'If I had not been for a trip from my stock-broker, I ------- thousands of dollars in doomed stocks.', 'was lost', 'have lost', 'would lost', 'would have lost', 'D', NULL, 'Nếu tôi không thông qua nhà môi giới chứng khoán của mình, tôi đã mất hàng ngàn đô la trong cổ phiếu thua lỗ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0043', 'pdf_database', '------- anyone wish to access the information on the status of his or her order, the password should be entered.', 'If', 'Should', 'Whether', 'As though', 'B', NULL, 'Nếu bất cứ ai muốn truy cập thông tin về trạng thái đơn đặt hàng của mình, mật khẩu nên được nhập.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0044', 'pdf_database', '------- it be necessary, you can print out your form and then send it to us by fax or postal service.', 'Since', 'Should', 'Unless', 'When', 'B', NULL, 'Nếu cần thiết, bạn có thể in biểu mẫu của mình và sau đó gửi cho chúng tôi bằng fax hoặc dịch vụ bưu chính.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0045', 'pdf_database', '------- Jonh worked hard, he would have been promoted last year.', 'If', 'Were', 'Should', 'Had', 'D', NULL, 'Nếu Jonh làm việc chăm chỉ, anh ấy đã được thăng chức vào năm ngoái.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0046', 'pdf_database', '------- the patient''s condition get worse, the nurse will call in an internist.', 'Might', 'Unless', 'Should', 'If', 'C', NULL, 'Nếu tình trạng của bệnh nhân trở nên tồi tệ hơn, y tá sẽ gọi bác sĩ nội khoa.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0047', 'pdf_database', '------- she wish to have more detailed information, please consult your employee handbook.', 'Would', 'Could', 'Might', 'Should', 'D', NULL, 'Nếu cô ấy muốn có thông tin chi tiết hơn, xin vui lòng tham khảo sổ tay nhân viên của bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0048', 'pdf_database', 'Should she ------- our offer, we will be glad to cooperate.', 'Accept', 'Accepts', 'Accepting', 'Accepted', 'A', NULL, 'Nếu cô ấy chấp nhận lời đề nghị của chúng tôi, chúng tôi sẽ vui mừng hợp tác.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0049', 'pdf_database', '------- the employee followed the safety procedures properly, the accident could have been avoided.', 'Having', 'Had', 'If', 'Has', 'B', NULL, 'Nếu nhân viên làm theo các quy trình an toàn đúng cách, tai nạn có thể tránh được.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0050', 'pdf_database', '------- I you, I would not behave like that.', 'If', 'Were', 'Should', 'Had', 'B', NULL, 'Nếu tôi là bạn, tôi sẽ không cư xử như vậy.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0051', 'pdf_database', 'Had the contract ------- early, we might have been able to discuss the conditions and make a decision.', 'deliver', 'delivered', 'been delivered', 'were delevered', 'C', NULL, 'Nếu hợp đồng được giao sớm, chúng tôi có thể thảo luận về các điều kiện và đưa ra quyết định.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0052', 'pdf_database', 'Had the team submited the report on schedule, the manager ------- to postpone the meeting with the board of Directors.', 'did not have', 'would not be had', 'would not had', 'would not have had', 'D', NULL, 'Nếu nhóm nộp báo cáo đúng tiến độ, người quản lý đã không phải hoãn cuộc họp với ban giám đốc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0053', 'pdf_database', '------- her rental application be denied, the owers will refund the cost of processing the application.', 'could', 'may', 'do', 'should', 'D', NULL, 'Nếu đơn xin thuê của cô ấy bị từ chối, những người cấp phép sẽ hoàn trả chi phí xử lý đơn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0054', 'pdf_database', 'Had we ------- that Mr.A had a case pending in criminal court, we could never have hired him for the job.', 'been known', 'knew', 'know', 'known', 'D', NULL, 'Nếu chúng tôi biết rằng Mr.A có một vụ án đang chờ xử lý tại tòa án hình sự, chúng tôi không bao giờ có thể thuê anh ta.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0055', 'pdf_database', 'Had the director been out of the country, his assistant ------- charge of ongoing projects during that time.', 'had taken', 'could have taken', 'were taking', 'will have taken', 'B', NULL, 'Nếu giám đốc đã ra khỏi đất nước, trợ lý của ông có thể đảm nhiệm các dự án đang diễn ra trong thời gian đó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0056', 'pdf_database', 'Had their systems been protected with a reliable anti-virus program, subscribers ------- no problems with their computer now.', 'will have', 'have', 'would have', 'had', 'C', NULL, 'Nếu hệ thống của họ được bảo vệ với chương trình chống vi-rút đáng tin cậy, người đăng ký sẽ không gặp vấn đề gì với máy tính của họ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0057', 'pdf_database', 'Had estimated figures been more accurate, strategists would ------- a better financial plan to tackle the budget.', 'create', 'be creating', 'have created', 'had been created', 'C', NULL, 'Nếu con số ước tính chính xác hơn, các chiến lược gia sẽ tạo ra một kế hoạch tài chính tốt hơn để giải quyết ngân sách.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0058', 'pdf_database', 'Had negotiations not broken down at the last minute, Laureano, Inc., -------with its main competitor, Trevino-Martin.', 'has merged', 'would have merged', 'had merged', 'will have merged', 'B', NULL, 'Nếu các cuộc đàm phán không bị phá vỡ vào phút cuối, Laureano, Inc., sẽ sáp nhập với đối thủ chính của nó, Trevino-Martin.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-b0059', 'pdf_database', 'Mr. Jung ------- his position as Chief Executive of Cosmic Gaming Company had the merger with Starzan Enterprises succeeded.', 'is being relinquished', 'would have relinquished', 'has been relinquishing', 'will be relinquished', 'B', NULL, 'Ông Jung sẽ từ bỏ vị trí như là Giám đốc điều hành của Cosmic Gaming Company nếu việc sáp nhập với Starzan Enterprises thành công.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0001', 'pdf_database_entry', 'If you (swim) -------- in this lake, you''ll shiver from cold.', 'swim', 'swimed', 'will swim', 'would swim', 'A', 'Dạng đúng cần điền là: ''swim''.', 'Nếu bạn bơi trong hồ này, bạn sẽ rùng mình vì lạnh.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0002', 'pdf_database_entry', 'If the milkman (come) _----------------, tell him to leave two pints.', 'comes', 'comed', 'will com', 'would com', 'A', 'Dạng đúng cần điền là: ''comes''.', 'Nếu người bán sữa đến, hãy bảo anh ta để lại hai panh.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0003', 'pdf_database_entry', 'I (call) _---------------- the office if I were you.', 'would call', 'would called', 'will would call', 'would would call', 'A', 'Dạng đúng cần điền là: ''would call''.', 'Tôi sẽ gọi điện cho văn phòng nếu tôi là bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0004', 'pdf_database_entry', 'Someone (sit) __----------------on your glasses if you leave them there.', 'will sit', 'will sited', 'will will sit', 'would will sit', 'A', 'Dạng đúng cần điền là: ''will sit''.', 'Ai đó sẽ ngồi lên kính của bạn nếu bạn để chúng ở đây.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0005', 'pdf_database_entry', 'You would hear my explanation if you (not talk) _--------__so much.', 'didn’t talk', 'didn’t talked', 'will didn’t talk', 'would didn’t talk', 'A', 'Dạng đúng cần điền là: ''didn’t talk''.', 'Bạn sẽ nghe lời giải thích của tôi nếu bạn không nói chuyện quá nhiều.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0006', 'pdf_database_entry', 'If you (read) _----------------the instructions carefully, you wouldn''t have answered the wrong question.', 'had read', 'had reaed', 'will had rea', 'would had rea', 'A', 'Dạng đúng cần điền là: ''had read''.', 'Nếu bạn đọc những hướng dẫn một cách cẩn thận, bạn sẽ không trả lời sai câu hỏi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0007', 'pdf_database_entry', 'If Mel (ask) _--------__ her teacher, he''d have answered her questions.', 'had asked', 'had ask', 'will had ask', 'would had ask', 'A', 'Dạng đúng cần điền là: ''had asked''.', 'Nếu Mel hỏi thầy giáo của cô ấy, ông ấy sẽ trả lời câu hỏi của cô.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0008', 'pdf_database_entry', 'We''ll have a long way to walk if we (run) ------------------------out of petrol here.', 'run', 'runed', 'will run', 'would run', 'A', 'Dạng đúng cần điền là: ''run''.', 'Chúng ta sẽ có một chặng đường dài để đi bộ nếu chúng ta hết xăng ở đây.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0009', 'pdf_database_entry', 'If I had known that you couldn''t eat octopus, I (not buy) -------- it.', 'wouldn’t have bought', 'wouldn’t have boughted', 'will wouldn’t have bought', 'would wouldn’t have bought', 'A', 'Dạng đúng cần điền là: ''wouldn’t have bought''.', 'Nếu tôi biết bạn không thể ăn bạch tuộc, tôi đã không mua nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0010', 'pdf_database_entry', 'If they (hang) __----------------that picture lower, people would be able to see it.', 'hung', 'hunged', 'will hung', 'would hung', 'A', 'Dạng đúng cần điền là: ''hung''.', 'Nếu họ treo bức tranh thấp hơn, mọi người có thể nhìn thấy nó.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-13-fb-0011', 'pdf_database_entry', 'Dan (arrive) __---------------- safe if he drove slowly.', 'would arrive', 'would arrived', 'will would arriv', 'would would arriv', 'A', 'Dạng đúng cần điền là: ''would arrive''.', 'Dan sẽ đến an toàn nếu anh ấy lái xe chậm.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0002', 'pdf_database', 'Production of recreational vehicles ------ significantly low this month.', 'are', 'have', 'is', 'be', 'C', NULL, 'Sản xuất phương tiện giải trí thấp đáng kể trong tháng này.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0003', 'pdf_database', 'New vacation policies which are under discussion ------ expected to be introduced early next month.', 'are', 'is', 'will', 'to be', 'A', NULL, 'Những chính sách nghỉ phép mới đang được thảo luận dự kiến sẽ được giới thiệu vào đầu tháng tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0004', 'pdf_database', 'The ------ for launching the new advertising campaign is posted on the bulletin board.', 'schedule', 'scheduled', 'schedules', 'schedulers', 'A', NULL, 'Lịch trình khởi động chiến dịch quảng cáo mới được đăng trên bảng tin.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0005', 'pdf_database', 'Any late entries which ------- submitted for the contest will not be considered.', 'is', 'being', 'will', 'are', 'D', NULL, 'Bất kỳ hồ sơ muộn nào được gửi cho cuộc thi sẽ không được xem xét.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0006', 'pdf_database', 'The solutions for the city''s traffic problems ------- to be considered individually.', 'needy', 'needs', 'needing', 'need', 'D', NULL, 'Các giải pháp cho các vấn đề giao thông của thành phố cần được xem xét riêng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0007', 'pdf_database', 'Following safety precautions ------- workers avoid any injury in the workplace.', 'helping', 'helps', 'to help', 'help', 'B', NULL, 'Tuân thủ các biện pháp phòng ngừa an toàn giúp công nhân tránh mọi chấn thương tại nơi làm việc.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0008', 'pdf_database', 'The Sunstar Hotel which has expanded both in size and quality ------- to attract more tourists in coming years.', 'expects', 'expectation', 'expecting', 'expect', 'A', NULL, 'Khách sạn Sunstar đã mở rộng cả về quy mô và chất lượng, dự kiến sẽ thu hút nhiều khách du lịch hơn trong những năm tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-14-b0009', 'pdf_database', 'International -------- for the service have not yet been analyzed by the firm.', 'market', 'marketing', 'markets', 'marketability', 'C', NULL, 'Các thị trường quốc tế cho dịch vụ vẫn chưa được phân tích bởi công ty.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0002', 'pdf_database', 'Dr. Suzuki arrived for the awards ceremony on time ------ her train had left twenty minutes late.', 'as if', 'even though', 'while', 'because', 'B', NULL, 'Bác sĩ Suzuki đến dự lễ trao giải đúng giờ mặc dù chuyến tàu của cô đã trễ hai mươi phút.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0003', 'pdf_database', 'Personnel must sign the register ------- removing any confidential papers from the organization''s vaults.', 'before', 'until', 'from', 'during', 'A', NULL, 'Nhân viên phải ký vào sổ đăng ký trước khi xóa bất kỳ giấy tờ bí mật nào khỏi kho tiền của tổ chức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0004', 'pdf_database', 'Tenants should call the property owner directly ------ problems with heating or plumbing are not resolved by the on-site manager.', 'if', 'why', 'due to', 'about', 'A', NULL, 'Người thuê nên gọi trực tiếp cho chủ sở hữu tài sản nếu vấn đề với hệ thống sưởi hoặc hệ thống ống nước không được giải quyết bởi người quản lý tại chỗ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0005', 'pdf_database', 'Arten Publishing has experienced an average annual growth of over 7 percent in sales ----- it went public twenty years ago.', 'if', 'since', 'how', 'than', 'B', NULL, 'Arten Publishing đã đạt mức tăng trưởng trung bình hàng năm trên 7% kể từ khi công khai hai mươi năm trước.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0006', 'pdf_database', 'Any employee working late on a Friday must remember to turn off all computer equipment ------ leaving for the night.', 'until', 'then', 'before', 'because', 'C', NULL, 'Bất kỳ nhân viên nào làm việc muộn vào thứ Sáu đều phải nhớ tắt tất cả các thiết bị máy tính trước khi về nhà.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0007', 'pdf_database', 'The company''s revenue during the next quarter will increase, ------- the lucrative contract with Kang Securities can be finalized before next month.', 'as if', 'whereas', 'whether', 'assuming that', 'D', NULL, 'Doanh thu của công ty trong quý tới sẽ tăng lên, giả sử rằng hợp đồng sinh lợi với Kang Securities có thể được hoàn tất trước tháng tới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0008', 'pdf_database', '------- she loves animals, Ms. Peters is a technician at the Eldridge Veterinary Center.', 'If', 'So', 'Unless', 'Since', 'D', NULL, 'Vì yêu động vật, cô Peters là một kỹ thuật viên tại Trung tâm thú y Eldridge.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0009', 'pdf_database', '------- you wish to see a complete list of hotel amenities, please refer to the informational binder on the desk in your guest room.', 'Whether', 'Despite', 'If', 'For', 'C', NULL, 'Nếu bạn muốn xem một danh sách đầy đủ các tiện nghi của khách sạn, vui lòng tham khảo các tờ thông tin trên bàn trong phòng khách của bạn.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0010', 'pdf_database', '------- receiving notice that the director of the Deerfield Orchestra will retire, the board of directors has been searching for a replacement.', 'Since', 'While', 'Once', 'Because', 'A', NULL, 'Kể từ khi nhận được thông báo rằng giám đốc của Dàn nhạc Deerfield sẽ nghỉ hưu, ban giám đốc đã tìm kiếm một người thay thế.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0011', 'pdf_database', 'Conference participants can get to the Wyatt Hotel ------ by train or by bus.', 'unless', 'both', 'either', 'without', 'C', NULL, 'Những người tham gia hội nghị có thể đến khách sạn Wyatt bằng tàu hỏa hoặc xe buýt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0012', 'pdf_database', '------ the order was placed after the sale had ended, no discount will be given.', 'However', 'During', 'Because', 'Yet', 'C', NULL, 'Bởi vì đơn đặt hàng đã được đặt sau khi việc bán hàng kết thúc, sẽ không có giảm giá.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0013', 'pdf_database', 'Hanti Food Corporation''s overall production costs rose -------the price of sugar and other staple ingredients increased.', 'because', 'so that', 'in order that', 'until', 'A', NULL, 'Chi phí sản xuất chung của Hanti Food Corporation tăng vì giá đường và các thành phần chính khác tăng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0014', 'pdf_database', '------- its electronic publishing division lost money last year, Gwangmyeong Press expects it to earn a profit this year.', 'Although', 'As soon as', 'When', 'Owing to', 'A', NULL, 'Mặc dù bộ phận xuất bản điện tử của nó đã mất tiền vào năm ngoái, Gwangmyeong Press hy vọng nó sẽ kiếm được lợi nhuận trong năm nay.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0015', 'pdf_database', 'The community fund-raiser was a great success -------Anna Borovsky and Martin Lawson, the organizers of the event.', 'in case of', 'as a result', 'thanks to', 'given that', 'C', NULL, 'Sự kiện gây quỹ cộng đồng là một thành công lớn nhờ Anna Borovsky và Martin Lawson, những người tổ chức sự kiện.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0016', 'pdf_database', 'Employees will have to record their work hours on the company Web site -------the payroll software update has been installed.', 'once', 'next', 'so that', 'such as', 'A', NULL, 'Nhân viên sẽ phải ghi lại giờ làm việc của họ trên trang web của công ty một khi việc cập nhật phần mềm bảng lương được cài đặt.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0017', 'pdf_database', '------- its major competitors, Keelan Air offers non-stop flights to hundreds of international destinations.', 'Unlike', 'Therefore', 'Nevertheless', 'Otherwise', 'A', NULL, 'Không giống như các đối thủ cạnh tranh lớn, Keelan Air cung cấp các chuyến bay thẳng đến hàng trăm điểm đến quốc tế.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0018', 'pdf_database', 'The confirmation e-mail will contain both a tracking number -------an approximate delivery date.', 'or', 'as', 'but', 'and', 'D', NULL, 'Email xác nhận sẽ chứa cả số theo dõi và ngày giao hàng gần đúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0019', 'pdf_database', 'Mr. Yakamoto recommended ------- Mr. Ono and Ms. Simmons for promotions.', 'both', 'and', 'if', 'either', 'A', NULL, 'Ông Yakamoto giới thiệu cả ông Ono và bà Simmons cho việc tăng chức.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0020', 'pdf_database', '-------the terms of the contract, Mulz Janitorial Service will clean all offices in the Lundquist Building daily.', 'As long as', 'Because', 'According to', 'In order that', 'C', NULL, 'Theo các điều khoản trong hợp đồng, Mulz Janitorial Service sẽ dọn dẹp tất cả các văn phòng trong Tòa nhà Lundquist hàng ngày.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0021', 'pdf_database', 'The community swimming pool is not to be used at any time -------a trained lifeguard is on duty.', 'in fact', 'unless', 'in case', 'otherwise', 'B', NULL, 'Hồ bơi cộng đồng sẽ không được sử dụng bất cứ lúc nào trừ khi nhân viên cứu hộ được đào tạo đang làm nhiệm vụ.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0022', 'pdf_database', '-------there had not been slight delays in the bus service to the airport, Ms. Suzuki would have caught her scheduled flight to Brussels.', 'If', 'Whereas', 'Unless', 'Even', 'A', NULL, 'Nếu không có sự chậm trễ nhỏ trong dịch vụ xe buýt đến sân bay, cô Suzuki sẽ bắt chuyến bay theo lịch trình của mình đến Brussels.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0023', 'pdf_database', 'After discussing the terms of the new healthbenefits contract, -------management and employees were satisfied.', 'both', 'also', 'either', 'too', 'A', NULL, 'Sau khi thảo luận về các điều khoản của hợp đồng lợi ích sức khỏe mới, cả quản lý và nhân viên đều hài lòng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0024', 'pdf_database', 'Employees currently working in Ridge Manufacturing''s branch offices will move into the new headquarters ------ the building is finished.', 'once', 'even', 'besides', 'moreover', 'A', NULL, 'Các nhân viên hiện đang làm việc trong các văn phòng chi nhánh của Ridge Sản xuất sẽ chuyển đến trụ sở mới một khi tòa nhà hoàn thành.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0025', 'pdf_database', 'In the decade ___ it was founded, Liu and Wang Corporation has become a legend in creative advertising.', 'since', 'almost', 'however', 'therefore', 'A', NULL, 'Trong thập kỷ kể từ khi được thành lập, Liu và Wang Corporation đã trở thành một huyền thoại trong quảng cáo sáng tạo.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0026', 'pdf_database', 'The Reyes Regional Theater will raise ticket prices this year ------- the expense of a new sound and lighting system.', 'out of', 'when', 'because', 'due to', 'D', NULL, 'Nhà hát khu vực Reyes sẽ tăng giá vé trong năm nay do chi phí cho một hệ thống âm thanh và ánh sáng mới.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0027', 'pdf_database', '-------- her experience in sales, Ms. Woo has a background in public relations.', 'Although', 'Besides', 'Whether', 'Until', 'B', NULL, 'Bên cạnh kinh nghiệm bán hàng, cô Woo còn có nền tảng về quan hệ công chúng.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0028', 'pdf_database', '------ Ms. Rajappan has been at the law firm for only two years, she has already worked on a large number of high-profile projects.', 'Although', 'Moreover', 'Despite', 'Yet', 'A', NULL, 'Mặc dù bà Rajappan đã ở công ty luật chỉ mới được hai năm, nhưng bà đã làm việc với một số lượng lớn các dự án cao cấp.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0029', 'pdf_database', '------ offering lightweight clothing, Hurvitz Travel Wear also sells stylish luggage and accessories.', 'Except', 'Besides', 'However', 'Unless', 'B', NULL, 'Bên cạnh việc cung cấp quần áo nhẹ, Hurvitz Travel Wear còn bán hành lý và phụ kiện thời trang.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0030', 'pdf_database', '------ the Kendal Company has been in business for only nine months, it has very quickly become profitable.', 'Although', 'Unless', 'Before', 'During', 'A', NULL, 'Mặc dù Công ty Kendal mới hoạt động được 9 tháng nhưng nó đã nhanh chóng có lãi.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
INSERT INTO grammar_questions (id, source_table, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation_vi, translation_vi, vocabulary) VALUES ('book_key-15-b0031', 'pdf_database', '-------- he arrives at the airport in the next ten minutes, Mr. Santini is going to have to take a later flight.', 'Regardless', 'While', 'Unless', 'Rather', 'C', NULL, 'Trừ khi ông đến sân bay trong mười phút tới, ông Santini sẽ phải đi chuyến bay sau.', NULL) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text), option_a=VALUES(option_a), option_b=VALUES(option_b), option_c=VALUES(option_c), option_d=VALUES(option_d), correct_answer=VALUES(correct_answer), explanation_vi=VALUES(explanation_vi), translation_vi=VALUES(translation_vi), vocabulary=VALUES(vocabulary);
